    withheld?: true;
    /** outlived its timeout; runs on, output streaming to outputPath */
    running?: {
        taskId: string;
        outputPath: string;
    };
    /** why the call failed outside the command (a denial, a refusal, an interruption); the shell tool's reading of its exit */
    error?: string;
    note?: string;
}
