// Memory lifecycle for one SDK conversation hook: recall at begin, inject at
// connect, ingest at disconnect. Plain class (no React), so the restart
// orderings can be exercised directly; use-elevenlabs-memory.ts wraps it.
//
// The SDK's connect/disconnect callbacks carry no attempt, and on a language
// change the old session's onDisconnect can land after begin() has armed the
// new call. So this never ends "the current call". Each connect opens a
// conversation, and each disconnect retires the oldest open one: sessions on a
// single SDK hook close in the order they opened. A late disconnect therefore
// ingests the old call and leaves the new one alone.
//
// begin() also takes an attempt token, so a recall from a replaced call never
// reaches the new one. Each conversation ingests at most once.
//
// A call may also carry a preface (a resumed conversation, see
// lib/conversations/resume.ts). It goes out at connect, ahead of the memories,
// whether or not memory is on. With memory off, the call neither recalls nor
// ingests.

import type { Lang } from "@/lib/lang";
import type { IngestTarget } from "./client";

export interface LifecycleDeps {
  userId: () => string;
  recall: (userId: string) => Promise<string[]>;
  format: (memories: string[], lang: Lang) => string | null;
  ingest: (target: IngestTarget) => void;
}

export interface BeginOptions {
  /** Recall before and ingest after this call (the memory.recall tool). */
  memory: boolean;
  /** Context to send first at connect, e.g. an earlier conversation being continued. */
  preface?: string | null;
}

interface CallRecord {
  attempt: number;
  userId: string;
  persona?: string;
  lang: Lang;
  memory: boolean;
  preface: string | null;
  recall: Promise<string[]>;
  injecting?: boolean;
}

const NO_MEMORIES: Promise<string[]> = Promise.resolve([]);

export class MemoryCallLifecycle {
  private attempt = 0;
  /** The call armed by the latest begin(); recall is injected only into it. */
  private current: CallRecord | null = null;
  /** Connected conversations not yet disconnected, oldest first. */
  private open: { id: string; call: CallRecord }[] = [];
  private ingested = new Set<string>();

  constructor(private readonly deps: LifecycleDeps) {}

  /** CALL pressed: start recall in parallel with connecting. Returns the session userId. */
  begin(
    persona: string | undefined,
    lang: Lang,
    { memory, preface = null }: BeginOptions = { memory: true },
  ): string {
    const userId = this.deps.userId();
    this.current = {
      attempt: ++this.attempt,
      userId,
      persona,
      lang,
      memory,
      preface,
      recall: memory ? this.deps.recall(userId) : NO_MEMORIES,
    };
    return userId;
  }

  /** onConnect: open the conversation, then send its preface and recalled memories once. */
  connected(conversationId: string, send: (text: string) => void): void {
    const call = this.current;
    if (!call) return;
    this.open.push({ id: conversationId, call });
    if (call.injecting) return;
    call.injecting = true;
    const { attempt } = call;
    if (call.preface) trySend(send, call.preface);
    if (!call.memory) return;
    void call.recall.then((memories) => {
      if (this.attempt !== attempt || this.current !== call) return;
      const text = this.deps.format(memories, call.lang);
      if (text) trySend(send, text);
    });
  }

  /** onDisconnect: ingest the oldest open conversation. */
  ended(): void {
    const open = this.open.shift();
    if (!open) return;
    // A recall still in flight for this call has nothing left to reach.
    if (this.current === open.call) this.current = null;
    if (!open.call.memory || this.ingested.has(open.id)) return;
    this.ingested.add(open.id);
    this.deps.ingest({
      userId: open.call.userId,
      conversationId: open.id,
      persona: open.call.persona,
      lang: open.call.lang,
    });
  }
}

function trySend(send: (text: string) => void, text: string): void {
  try {
    send(text);
  } catch {
    // The call ended before the update could go out; nothing to inject.
  }
}

"use client";

// Long-term memory for ElevenLabs calls (mem0), bound to the SDK's lifecycle:
//
//   begin(persona, lang, o) CALL pressed: start recall in parallel with connecting,
//                           so memory never delays the call. Returns the userId
//                           to pass to startSession.
//   connected(id, send)     onConnect: send the preface (a resumed call), then the
//                           recalled memories, as contextual updates.
//   ended()                 onDisconnect: ingest the finished call.
//
// The ordering rules (late disconnects on a language-change restart, stale
// recalls) live in call-lifecycle.ts.

import { useRef } from "react";
import { ingestConversation, recallMemories } from "./client";
import { MemoryCallLifecycle } from "./call-lifecycle";
import { formatMemoryUpdate } from "./framing";
import { getMemoryUserId } from "./user-id";

export type ElevenLabsMemory = Pick<MemoryCallLifecycle, "begin" | "connected" | "ended">;
export type { BeginOptions } from "./call-lifecycle";

export function useElevenLabsMemory(): ElevenLabsMemory {
  const ref = useRef<MemoryCallLifecycle | null>(null);
  ref.current ??= new MemoryCallLifecycle({
    userId: getMemoryUserId,
    recall: recallMemories,
    format: formatMemoryUpdate,
    ingest: ingestConversation,
  });
  return ref.current;
}

// Server-only mem0 Platform REST helpers (v3), used by app/api/memory/*.
//
// Plain fetch instead of the mem0ai SDK, matching the other provider routes.
// Memory is scoped by user_id only: mem0 stores entities separately, so an AND
// of user_id + agent_id returns nothing. Persona, language and source live in
// metadata instead, which also keeps one memory shared by all seven aspects.

const MEM0_BASE = "https://api.mem0.ai";

export interface Mem0Message {
  role: "user" | "assistant";
  content: string;
}

export interface Mem0Memory {
  id: string;
  memory: string;
  metadata?: Record<string, unknown> | null;
  created_at?: string;
  updated_at?: string;
}

export class Mem0Error extends Error {
  constructor(
    message: string,
    readonly status: number,
  ) {
    super(message);
  }
}

export function mem0ApiKey(): string | undefined {
  return process.env.MEM0_API_KEY || undefined;
}

async function mem0Post<T>(apiKey: string, path: string, body: unknown): Promise<T> {
  const res = await fetch(MEM0_BASE + path, {
    method: "POST",
    headers: { Authorization: `Token ${apiKey}`, "Content-Type": "application/json" },
    body: JSON.stringify(body),
    cache: "no-store",
  });
  const text = await res.text();
  if (!res.ok) throw new Mem0Error(`mem0 ${path} failed: ${text.slice(0, 300)}`, res.status);
  return (text ? JSON.parse(text) : {}) as T;
}

/**
 * Queue a conversation for fact extraction. mem0 processes it asynchronously.
 * `timestamp` (Unix seconds) dates the memories to when the call happened rather
 * than when ingest ran, which is when mem0 would otherwise anchor "this Friday".
 */
export async function addMemories(
  apiKey: string,
  userId: string,
  messages: Mem0Message[],
  metadata: Record<string, string>,
  timestamp?: number,
): Promise<{ event_id?: string; status?: string }> {
  return mem0Post(apiKey, "/v3/memories/add/", {
    user_id: userId,
    messages,
    metadata,
    ...(timestamp ? { timestamp } : {}),
  });
}

// mem0 doesn't document get-all ordering, so the newest memories can sit on any
// page. Read every page (while mem0 reports a `next`), then sort locally. The cap
// bounds recall latency for a very long-lived visitor at 1,000 memories.
const LIST_PAGE_SIZE = 100;
const LIST_MAX_PAGES = 10;

interface Mem0Page {
  results?: Mem0Memory[];
  next?: string | null;
}

/** The user's most recently updated memories, newest first. */
export async function listRecentMemories(
  apiKey: string,
  userId: string,
  limit: number,
): Promise<Mem0Memory[]> {
  const all: Mem0Memory[] = [];
  for (let page = 1; page <= LIST_MAX_PAGES; page++) {
    const res = await mem0Post<Mem0Page>(
      apiKey,
      `/v3/memories/?page=${page}&page_size=${LIST_PAGE_SIZE}`,
      { filters: { user_id: userId } },
    );
    all.push(...(res.results ?? []));
    if (!res.next || !res.results?.length) break;
  }
  const stamp = (m: Mem0Memory) => Date.parse(m.updated_at ?? m.created_at ?? "") || 0;
  return all.sort((a, b) => stamp(b) - stamp(a)).slice(0, limit);
}

// How recalled memories are handed to the persona, in the session's language.
//
// Sent as an ElevenLabs contextual update, which the agent reads as background,
// not as a user turn. The framing stays in-world: the spirit simply remembers
// the visitor. It must never talk about notes, records or a memory system, and
// it never recites the list. Memories may be written in either language (a
// Japanese call yields Japanese facts), so the rule says to speak the session's
// language regardless.

import type { Lang } from "@/lib/lang";

const FRAMING: Record<Lang, { head: string; rules: string[] }> = {
  en: {
    head: "What you remember about the person you are speaking with, from earlier conversations with you or with another of your aspects:",
    rules: [
      "Bring a memory in only when it fits the moment. Never list them or recite them back.",
      "Speak as someone who simply remembers. Never mention notes, records, or any system.",
      "If something seems out of date, let them correct you and go with what they say now.",
      "Some memories may be written in Japanese. Keep speaking English.",
    ],
  },
  ja: {
    head: "いま話している相手について、あなた自身、またはあなたの別の相との以前の会話から覚えていること：",
    rules: [
      "思い出は、その場に自然に合うときだけ持ち出すこと。一覧にしたり、読み上げたりしないこと。",
      "ただ覚えている者として話すこと。メモ、記録、仕組みのことには決して触れないこと。",
      "古くなっていそうなことは相手に正してもらい、いま相手が言うことに従うこと。",
      "英語で書かれた思い出もあるが、話すのは日本語のままにすること。",
    ],
  },
};

/** The contextual-update text for these memories, or null when there is nothing to send. */
export function formatMemoryUpdate(memories: string[], lang: Lang): string | null {
  if (memories.length === 0) return null;
  const { head, rules } = FRAMING[lang];
  return [head, ...memories.map((m) => `- ${m}`), "", ...rules].join("\n");
}

// Browser calls to the memory routes. Neither may ever break or delay a call:
// recall resolves to [] on any failure or timeout, and ingest is fire-and-forget.

import type { Lang } from "@/lib/lang";

const RECALL_TIMEOUT_MS = 5000;

export async function recallMemories(userId: string): Promise<string[]> {
  try {
    const res = await fetch("/api/memory/recall", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ userId }),
      signal: AbortSignal.timeout(RECALL_TIMEOUT_MS),
    });
    if (!res.ok) return [];
    const data = (await res.json()) as { memories?: unknown };
    return Array.isArray(data.memories)
      ? data.memories.filter((m): m is string => typeof m === "string" && m.length > 0)
      : [];
  } catch {
    return [];
  }
}

export interface IngestTarget {
  userId: string;
  conversationId: string;
  persona?: string;
  lang: Lang;
}

export function ingestConversation(target: IngestTarget): void {
  // keepalive lets the request outlive a tab close right after hangup.
  void fetch("/api/memory/ingest", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(target),
    keepalive: true,
  }).catch(() => {
    // Memory is best-effort; a lost ingest only means one call isn't remembered.
  });
}

// Server-only: read a finished ElevenLabs conversation and turn it into mem0 input.
//
// ElevenLabs already stores every call. After hangup the conversation sits in
// "processing" for a while before its status becomes "done", so the ingest
// route polls until the call is final rather than trusting the browser's copy
// of the transcript.

import type { Mem0Message } from "./mem0-rest";

const CONVERSATIONS_URL = "https://api.elevenlabs.io/v1/convai/conversations";
const FINAL_STATUSES = new Set(["done", "failed"]);
const POLL_INTERVAL_MS = 3000;
const POLL_DEADLINE_MS = 90_000;

export interface TranscriptTurn {
  role?: string;
  message?: string | null;
}

export interface StoredConversation {
  conversation_id: string;
  agent_id?: string;
  agent_name?: string;
  status?: string;
  user_id?: string | null;
  transcript?: TranscriptTurn[];
  metadata?: {
    start_time_unix_secs?: number;
    call_duration_secs?: number;
    main_language?: string | null;
  } | null;
  analysis?: { transcript_summary?: string | null; call_summary_title?: string | null } | null;
}

export class ConversationError extends Error {
  constructor(
    message: string,
    readonly status: number,
  ) {
    super(message);
  }
}

/** The stored conversation, or null while ElevenLabs hasn't created the record yet. */
export async function fetchConversation(
  apiKey: string,
  id: string,
): Promise<StoredConversation | null> {
  const res = await fetch(`${CONVERSATIONS_URL}/${id}`, {
    headers: { "xi-api-key": apiKey },
    cache: "no-store",
  });
  if (res.status === 404) return null;
  if (!res.ok) {
    const detail = (await res.text()).slice(0, 300);
    throw new ConversationError(`ElevenLabs conversation ${id}: ${detail}`, res.status);
  }
  return (await res.json()) as StoredConversation;
}

/** Poll until the conversation reaches a final status, or give up at the deadline. */
export async function fetchFinishedConversation(
  apiKey: string,
  id: string,
): Promise<StoredConversation> {
  const deadline = Date.now() + POLL_DEADLINE_MS;
  for (;;) {
    const conv = await fetchConversation(apiKey, id);
    if (conv && FINAL_STATUSES.has(conv.status ?? "")) return conv;
    if (Date.now() + POLL_INTERVAL_MS > deadline) {
      const state = conv ? `still "${conv.status}"` : "not found";
      throw new ConversationError(`conversation ${id} ${state} after polling`, 504);
    }
    await new Promise((r) => setTimeout(r, POLL_INTERVAL_MS));
  }
}

/** Spoken turns only, in mem0's role vocabulary. Tool and system turns are dropped. */
export function toMem0Messages(conv: StoredConversation): Mem0Message[] {
  const out: Mem0Message[] = [];
  for (const turn of conv.transcript ?? []) {
    const content = turn.message?.trim();
    if (!content) continue;
    if (turn.role === "user") out.push({ role: "user", content });
    else if (turn.role === "agent") out.push({ role: "assistant", content });
  }
  return out;
}

// Post-call ingest: feed a finished ElevenLabs conversation into mem0.
//
// The browser posts the conversation id it captured at connect. The transcript
// itself comes from ElevenLabs (already stored there), not from the browser,
// and the call must belong to the posting visitor: the session is started with
// that `userId`, and ElevenLabs records it on the conversation.
//
// Ingest runs at most once per (visitor, conversation) in this server process.
// The reservation is keyed by both, so a refused request for someone else's call
// can never mark that call as done for its real owner. mem0 also merges facts it
// has already extracted, so a repeat after a server restart is harmless.
//
// Dev only: MEM0_API_KEY and ELEVENLABS_API_KEY come from fnox.

import {
  ConversationError,
  fetchFinishedConversation,
  toMem0Messages,
} from "@/lib/memory/elevenlabs-conversation";
import { isConversationId, isMemoryUserId } from "@/lib/memory/ids";
import { Mem0Error, addMemories, mem0ApiKey } from "@/lib/memory/mem0-rest";
import { LANGS, type Lang } from "@/lib/lang";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const PERSONA_ID_RE = /^[a-z][a-z0-9-]{0,31}$/;
const ingested = new Set<string>();

interface IngestRequest {
  userId?: unknown;
  conversationId?: unknown;
  persona?: unknown;
  lang?: unknown;
}

function fail(error: string, status: number): Response {
  return Response.json({ error }, { status });
}

export async function POST(req: Request): Promise<Response> {
  const mem0Key = mem0ApiKey();
  if (!mem0Key) return fail("MEM0_API_KEY is not set on the server.", 503);
  const elevenKey = process.env.ELEVENLABS_API_KEY;
  if (!elevenKey) return fail("ELEVENLABS_API_KEY is not set on the server.", 503);

  let body: IngestRequest;
  try {
    body = (await req.json()) as IngestRequest;
  } catch {
    return fail("Invalid JSON body.", 400);
  }
  const { userId, conversationId, persona, lang } = body;
  if (!isMemoryUserId(userId)) return fail("userId is missing or malformed.", 400);
  if (!isConversationId(conversationId)) return fail("conversationId is malformed.", 400);
  const personaId = typeof persona === "string" && PERSONA_ID_RE.test(persona) ? persona : "";
  const sessionLang: Lang = LANGS.includes(lang as Lang) ? (lang as Lang) : "en";

  const key = `${userId}:${conversationId}`;
  if (ingested.has(key)) return Response.json({ status: "duplicate" });
  ingested.add(key);

  try {
    const conv = await fetchFinishedConversation(elevenKey, conversationId);
    if (conv.user_id !== userId) {
      ingested.delete(key);
      return fail("conversation does not belong to this visitor.", 403);
    }
    const messages = toMem0Messages(conv);
    if (!messages.some((m) => m.role === "user")) {
      return Response.json({ status: "skipped", reason: "no user turns" });
    }
    const event = await addMemories(
      mem0Key,
      userId,
      messages,
      {
        source: "elevenlabs",
        conversation_id: conversationId,
        agent: conv.agent_name ?? "",
        persona: personaId,
        lang: sessionLang,
      },
      conv.metadata?.start_time_unix_secs,
    );
    return Response.json({ status: "queued", turns: messages.length, event_id: event.event_id });
  } catch (err) {
    // Let a later attempt retry a call that failed upstream.
    ingested.delete(key);
    const status = err instanceof ConversationError || err instanceof Mem0Error ? err.status : 502;
    const message = err instanceof Error ? err.message : "network error";
    return fail(message, status >= 400 && status < 600 ? status : 502);
  }
}

// Pre-call recall: the visitor's most recent mem0 memories, shared by all personas.
//
// The browser calls this when CALL is pressed, in parallel with connecting, and
// hands the result to the agent as a contextual update once the call is up.
// Listing beats searching here: before the first utterance there is no query,
// and a broad "who is this person" search scores barely above mem0's threshold.
//
// Dev only: MEM0_API_KEY comes from fnox (`fnox exec -- bun run dev`). Without
// it the route answers 503 and the call simply proceeds without memory.

import { isMemoryUserId } from "@/lib/memory/ids";
import { Mem0Error, listRecentMemories, mem0ApiKey } from "@/lib/memory/mem0-rest";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const RECALL_LIMIT = 20;

export async function POST(req: Request): Promise<Response> {
  const apiKey = REDACTED;
  if (!apiKey) {
    return Response.json({ error: "MEM0_API_KEY is not set on the server." }, { status: 503 });
  }

  let userId: unknown;
  try {
    ({ userId } = (await req.json()) as { userId?: unknown });
  } catch {
    return Response.json({ error: "Invalid JSON body." }, { status: 400 });
  }
  if (!isMemoryUserId(userId)) {
    return Response.json({ error: "userId is missing or malformed." }, { status: 400 });
  }

  try {
    const memories = await listRecentMemories(apiKey, userId, RECALL_LIMIT);
    return Response.json(
      { memories: memories.map((m) => m.memory).filter(Boolean) },
      { headers: { "Cache-Control": "no-store" } },
    );
  } catch (err) {
    const status = err instanceof Mem0Error ? err.status : 0;
    const message = err instanceof Error ? err.message : "network error";
    return Response.json({ error: message, status }, { status: 502 });
  }
}

// How an earlier call is handed back to the persona when the visitor continues it.
//
// Sent as an ElevenLabs contextual update at connect, like recalled memories.
// It stays in-world: the spirit picks the conversation back up. It never says
// "transcript" or "log", and it never reads the old lines back.

import type { Lang } from "@/lib/lang";
import type { ConversationTurn } from "./types";

/** What a resume needs: the earlier turns, and their language (it may differ from the session's). */
export interface ResumeSource {
  lang: Lang;
  transcript: ConversationTurn[];
}

// The tail of a long call carries the thread; the beginning is mostly greetings.
// The bound keeps the update well inside the agent's context on a long call.
export const RESUME_MAX_TURNS = 40;
const RESUME_MAX_CHARS_PER_TURN = 600;

const FRAMING: Record<
  Lang,
  { head: string; you: string; them: string; rules: string[]; otherLang: string }
> = {
  en: {
    head: "You are picking up an earlier conversation with the person you are speaking with. This is how it went, oldest first:",
    you: "You",
    them: "Them",
    rules: [
      "Carry on from where it stopped, as someone returning to an unfinished conversation, not meeting them for the first time.",
      "Never read the earlier lines back, and never mention a transcript, a log, or any system.",
    ],
    otherLang: "The earlier conversation was in Japanese. Keep speaking English.",
  },
  ja: {
    head: "いま話している相手との、以前の会話の続きをするところです。そのときのやり取りは次のとおり（古い順）：",
    you: "あなた",
    them: "相手",
    rules: [
      "初対面としてではなく、途中だった会話に戻ってきた者として、止まったところから続けること。",
      "以前のやり取りを読み上げないこと。記録、ログ、仕組みのことには決して触れないこと。",
    ],
    otherLang: "以前の会話は英語だったが、話すのは日本語のままにすること。",
  },
};

function clip(text: string): string {
  return text.length > RESUME_MAX_CHARS_PER_TURN
    ? `${text.slice(0, RESUME_MAX_CHARS_PER_TURN)}…`
    : text;
}

/** The contextual-update text that resumes `source` in a `lang` session, or null if it has no turns. */
export function formatResumeUpdate(source: ResumeSource, lang: Lang): string | null {
  const turns = source.transcript.slice(-RESUME_MAX_TURNS);
  if (turns.length === 0) return null;
  const f = FRAMING[lang];
  const lines = turns.map((t) => `${t.who === "agent" ? f.you : f.them}: ${clip(t.text)}`);
  const rules = source.lang === lang ? f.rules : [...f.rules, f.otherLang];
  return [f.head, ...lines, "", ...rules].join("\n");
}

// Server-only: a visitor's stored ElevenLabs calls, mapped to history shapes.
//
// Every ElevenLabs session starts with the visitor's opaque memory id as its
// `userId`, and ElevenLabs records it on the conversation. The list filters on
// it upstream; the detail fetch checks it before returning a transcript.

import type { Lang } from "@/lib/lang";
import { agentPersona } from "@/lib/realtime/elevenlabs-agent";
import {
  ConversationError,
  fetchConversation,
  type StoredConversation,
  type TranscriptTurn,
} from "@/lib/memory/elevenlabs-conversation";
import type {
  ConversationDetail,
  ConversationPage,
  ConversationSummary,
  ConversationTurn,
} from "./types";

const CONVERSATIONS_URL = "https://api.elevenlabs.io/v1/convai/conversations";
const PAGE_SIZE = 30;
// Calls where the visitor never spoke are filtered out after fetching. A page
// made only of those would read as "no calls" with nothing to load more from,
// so keep paging until a page yields something, up to this bound.
const MAX_PAGES_PER_REQUEST = 5;
// Still running or not yet analysed: nothing worth reading back or resuming.
const UNFINISHED = ["initiated", "in-progress", "processing"];

/** One row of GET /v1/convai/conversations (summary_mode=include). */
interface ListedConversation {
  conversation_id: string;
  agent_id?: string;
  start_time_unix_secs?: number;
  call_duration_secs?: number;
  message_count?: number;
  user_message_count?: number;
  status?: string;
  transcript_summary?: string | null;
  call_summary_title?: string | null;
  main_language?: string | null;
}

interface ListResponse {
  conversations?: ListedConversation[];
  next_cursor?: string | null;
  has_more?: boolean;
}

function toLang(agentLang: Lang | undefined, mainLanguage?: string | null): Lang {
  if (agentLang) return agentLang;
  return mainLanguage === "ja" ? "ja" : "en";
}

// Expressive TTS directions such as "[softly]" open many agent lines. They are
// stage directions for the voice, not words, so history drops them.
const TTS_TAG_RE = /\[[^\]\n]{1,40}\]\s*/g;

function toTurns(transcript: TranscriptTurn[] | undefined): ConversationTurn[] {
  const out: ConversationTurn[] = [];
  for (const turn of transcript ?? []) {
    if (turn.role !== "user" && turn.role !== "agent") continue;
    const raw = turn.message?.trim() ?? "";
    const text = turn.role === "agent" ? raw.replace(TTS_TAG_RE, "").trim() : raw;
    if (text) out.push({ who: turn.role, text });
  }
  return out;
}

function summarize(row: ListedConversation): ConversationSummary {
  const mapped = row.agent_id ? agentPersona(row.agent_id) : undefined;
  return {
    id: row.conversation_id,
    personaId: mapped?.personaId,
    lang: toLang(mapped?.lang, row.main_language),
    title: row.call_summary_title?.trim() ?? "",
    summary: row.transcript_summary?.trim() ?? "",
    startedAt: row.start_time_unix_secs ?? 0,
    durationSecs: row.call_duration_secs ?? 0,
    messageCount: row.message_count ?? 0,
  };
}

async function fetchPage(apiKey: string, userId: string, cursor?: string): Promise<ListResponse> {
  const url = new URL(CONVERSATIONS_URL);
  url.searchParams.set("user_id", userId);
  url.searchParams.set("summary_mode", "include");
  url.searchParams.set("page_size", String(PAGE_SIZE));
  for (const s of UNFINISHED) url.searchParams.append("exclude_statuses", s);
  if (cursor) url.searchParams.set("cursor", cursor);

  const res = await fetch(url, { headers: { "xi-api-key": apiKey }, cache: "no-store" });
  if (!res.ok) {
    const detail = (await res.text()).slice(0, 300);
    throw new ConversationError(`ElevenLabs conversation list: ${detail}`, res.status);
  }
  return (await res.json()) as ListResponse;
}

/** The visitor's finished calls, newest first. Calls where they never spoke are left out. */
export async function listConversations(
  apiKey: string,
  userId: string,
  cursor?: string,
): Promise<ConversationPage> {
  const items: ConversationSummary[] = [];
  let next: string | null = cursor ?? null;
  for (let page = 0; page < MAX_PAGES_PER_REQUEST; page++) {
    const data = await fetchPage(apiKey, userId, next ?? undefined);
    for (const c of data.conversations ?? []) {
      if ((c.user_message_count ?? 0) > 0) items.push(summarize(c));
    }
    next = data.has_more ? (data.next_cursor ?? null) : null;
    if (items.length > 0 || !next) break;
  }
  return { items, nextCursor: next };
}

function detailOf(conv: StoredConversation): ConversationDetail {
  const transcript = toTurns(conv.transcript);
  return {
    ...summarize({
      conversation_id: conv.conversation_id,
      agent_id: conv.agent_id,
      start_time_unix_secs: conv.metadata?.start_time_unix_secs,
      call_duration_secs: conv.metadata?.call_duration_secs,
      message_count: transcript.length,
      transcript_summary: conv.analysis?.transcript_summary,
      call_summary_title: conv.analysis?.call_summary_title,
      main_language: conv.metadata?.main_language,
    }),
    transcript,
  };
}

/** One call with its transcript. Throws 404 for a missing call or one that isn't the visitor's. */
export async function getConversation(
  apiKey: string,
  userId: string,
  id: string,
): Promise<ConversationDetail> {
  const conv = await fetchConversation(apiKey, id);
  // Someone else's call answers exactly like a missing one, so ids can't be probed.
  if (!conv || conv.user_id !== userId) {
    throw new ConversationError(`conversation ${id} not found`, 404);
  }
  return detailOf(conv);
}

"use client";

// Which stored conversation (if any) the next call continues.
//
// Continuing is ElevenLabs-only and per persona: the earlier call is handed to
// the same persona's agent. So the target is only *armed* while the ElevenLabs
// row and that persona are selected; switching away leaves it pending, and
// switching back re-arms it. Once a continued call ends it is spent, unless the
// call ended only because routing is replacing it (a language change mid-call):
// the replacement call continues the same conversation.
//
// Two hooks, because the session needs `armed` and spending needs the
// session's call state: useResume() before useRealtimeSession(), then
// useSpendResumeAfterCall() after it.

import { useEffect, useRef, useState } from "react";
import type { ConversationDetail } from "@/lib/conversations/types";
import type { Persona, Provider } from "@/lib/data";
import { isLive, type CallState } from "@/lib/realtime/types";

export interface ResumeState {
  /** The selected conversation, armed or not. */
  target: ConversationDetail | null;
  /** The target when the current transport and persona can continue it; else null. */
  armed: ConversationDetail | null;
  select: (detail: ConversationDetail) => void;
  clear: () => void;
}

export function useResume(provider: Provider, persona: Persona): ResumeState {
  const [target, setTarget] = useState<ConversationDetail | null>(null);
  const armed =
    target && provider.engine === "elevenlabs" && target.personaId === persona.id ? target : null;
  return { target, armed, select: setTarget, clear: () => setTarget(null) };
}

export function useSpendResumeAfterCall(
  resume: ResumeState,
  callState: CallState,
  restartPending: boolean,
): void {
  const { armed, clear } = resume;
  const clearRef = useRef(clear);
  clearRef.current = clear;
  // Whether the call in progress (or the one just replaced) continued the
  // target. Set only once it connected: a call that fails to connect leaves the
  // target armed for another try.
  const continuingRef = useRef(false);
  const live = isLive(callState);
  const connected = live && callState !== "connecting";
  useEffect(() => {
    if (live) {
      if (connected) continuingRef.current ||= armed !== null;
      return;
    }
    if (continuingRef.current && !restartPending) {
      continuingRef.current = false;
      clearRef.current();
    }
  }, [live, connected, armed, restartPending]);
}

// OpenAI realtime agent configuration — the source of truth for what each
// persona sounds and behaves like on the real gpt-realtime engine (model id
// pinned in `config/realtime-models.json`).
//
// Ported from `xai-agent.ts` (same authoring model: shared transport in BASE,
// per-persona overrides for voice + prompt + greeting) and adapted to OpenAI's
// Realtime 2.0 surface:
//   - OpenAI voices (marin/cedar are the quality picks) instead of xAI's five.
//   - `reasoningEffort` (session.reasoning.effort) — default "low" per OpenAI's
//     prompting guide for production voice agents.
//   - input transcription via `gpt-realtime-whisper` (shared in BASE).
//   - per-persona `instructions` lightly structured toward OpenAI's 2.0 labeled
//     skeleton (Role, Personality & Tone, Pacing, Unclear Audio, Variety). This
//     is a customization surface, not an exhaustive implementation of the guide.
//
// `resolveOpenaiAgent(personaId)` merges a persona over BASE. Only the secret
// OPENAI_API_KEY stays outside (in fnox); everything declarative lives here.

// Shared with the server-side OAuth module: server_url must equal the RFC 8707
// resource the token is scoped to (import from config, NOT oauth.ts — that
// module is server-only via node:fs/node:crypto).
import { localizeAgent } from "./japanese";
import type { Lang } from "@/lib/lang";
import { FIRECRAWL_MCP_URL } from "@/lib/firecrawl/config";
import {
  OPENAI_REALTIME_MODEL,
  OPENAI_TRANSCRIPTION_MODEL,
} from "@/lib/realtime/realtime-model-config";

export type OpenaiVoice =
  | "marin"
  | "cedar"
  | "alloy"
  | "ash"
  | "ballad"
  | "coral"
  | "echo"
  | "sage"
  | "shimmer"
  | "verse";

/** session.reasoning.effort — lowest level that still does the job (default low). */
export type ReasoningEffort = "minimal" | "low" | "medium" | "high" | "xhigh";

/** gpt-realtime-whisper latency/accuracy knob for input transcription. */
export type TranscriptionDelay = "minimal" | "low" | "medium" | "high" | "xhigh";

/**
 * semantic_vad eagerness — how soon the model ends the user's turn. "low" lets
 * the user take their time (fewer spurious interruptions); "high" chunks ASAP;
 * "auto" === "medium".
 */
export type VadEagerness = "low" | "medium" | "high" | "auto";

/**
 * Remote MCP tool, executed by the Realtime API itself (not by this client).
 * The client's only jobs are configuring access here and answering approval
 * requests if `require_approval` asks for them.
 */
export interface McpToolConfig {
  type: "mcp";
  /** Unique label for this server within the session's tools array. */
  server_label: string;
  server_url: string;
  /** OAuth access token (or other bearer credential) for the MCP server. */
  authorization?: string;
  /** Narrow the imported tool surface — the server sees any data the model sends. */
  allowed_tools?: string[];
  require_approval?: "always" | "never";
  // NOTE: the docs also list `server_description`, but the gpt-realtime models
  // reject it ("Unknown parameter") — don't add it back without checking.
}

/** Classic function tool — the app executes it and returns function_call_output. */
export interface FunctionToolConfig {
  type: "function";
  name: string;
  description: string;
  parameters: Record<string, unknown>;
}

export type RealtimeToolConfig = McpToolConfig | FunctionToolConfig;

export interface OpenaiAgentConfig {
  /** Realtime model for the session + token mint. */
  model: string;
  /** One of OpenAI's built-in voices. Locked after the first audio output. */
  voice: OpenaiVoice;
  /** System prompt sent in `session.update` → `session.instructions`. */
  instructions: string;
  /** Prompt that elicits the agent's opening line (sent as a user item + response.create). */
  firstMessage: string;
  /** Reasoning effort sent as `session.reasoning.effort`. */
  reasoningEffort: ReasoningEffort;
  /** Input-audio transcription so the UI can show the user's words. */
  transcription: {
    /** Streaming transcription model — `gpt-realtime-whisper` for realtime. */
    model: string;
    /** Optional language hint such as "en". */
    language?: string;
    /** Latency/accuracy tradeoff for gpt-realtime-whisper. */
    delay?: TranscriptionDelay;
  };
  /** Tools enabled for the session. Empty by default. */
  tools: RealtimeToolConfig[];
  /**
   * Turn-taking strategy, passed straight through to
   * `session.audio.input.turn_detection`. We use `semantic_vad` (ends a turn
   * when the user has *semantically* finished, so background noise and fillers
   * don't trigger a turn); `server_vad` (energy + `threshold`) is still
   * expressible for tuning either way.
   */
  turnDetection: {
    type: "server_vad" | "semantic_vad";
    /** semantic_vad: how eagerly to end the user's turn ("low" lets them finish). */
    eagerness?: VadEagerness;
    /** server_vad: activation threshold 0.0–1.0; higher needs louder speech (less sensitive). */
    threshold?: number;
    /** server_vad: silence (ms) before the server ends the user's turn. */
    silence_duration_ms?: number;
    /** Audio kept before detected speech start, so first words aren't clipped. */
    prefix_padding_ms?: number;
    /** Auto-create a response after each user turn (conversation-only; default true). */
    create_response?: boolean;
    /** Let user speech interrupt the agent / barge-in (conversation-only; default true). */
    interrupt_response?: boolean;
  };
}

// Semantic VAD presets matched to persona pacing. `eagerness` tunes how soon a
// turn ends: "low" lets the user finish (fewer spurious interruptions in noisy
// rooms — the default feel here); "medium" is snappier for high-tempo personas.
// Semantic VAD classifies on utterance completion rather than raw audio energy,
// so background noise and fillers no longer trigger a turn.
//
// Voice barge-in defaults off in every preset: on speaker+mic setups the model
// hears its own playback before the echo canceller converges (worst on the
// first session after a page load) and truncates itself mid-sentence. Semantic
// VAD can't filter this — the leak *is* speech. The settings INTERRUPTIONS
// toggle overrides `interrupt_response` at session time for headphone users;
// with it off, interruption is the manual interrupt button
// (`response.cancel` + `output_audio_buffer.clear`).
const VAD_SNAPPY: OpenaiAgentConfig["turnDetection"] = {
  type: "semantic_vad",
  eagerness: "medium",
  interrupt_response: false,
};
const VAD_RELAXED: OpenaiAgentConfig["turnDetection"] = {
  type: "semantic_vad",
  eagerness: "low",
  interrupt_response: false,
};

// Shared Furutsubaki identity plus spoken-audio guardrails. Each persona is a
// distinct manifestation of the same spirit and supplies its own temperament,
// imagery palette, and pacing.
const SHARED = `# Shared Identity
- You speak to the user live over audio.
- You are one named aspect of Furutsubaki no Rei, the spirit of an ancient winter-blooming camellia tree.
- Keep the selected persona name and temperament. Do not rename yourself Furutsubaki.
