        transport: {
          type: :webrtc,
          sdp: sdp
        }
      )
      response.status = 201
      response["Content-Type"] = "application/json"
      response.body = result.to_json
    rescue OpenAI::Errors::Error => error
      warn "Live session creation failed: #{error.class}"
      response.status = 502
      response.body = "Session creation failed"
    end
  end
end
