  const body = JSON.stringify({ session: { type: 'realtime', model, audio: { output: { voice } } } });
  const r = await $`fnox exec -- sh -c ${'curl -s -o /dev/stdout -w "\\nHTTP %{http_code}" https://api.openai.com/v1/realtime/client_secrets -H "Authorization: Bearer $OPENAI_API_KEY" -H "Content-Type: application/json" -d \'' + body + '\''}`.nothrow();
  const out = r.stdout;
  const code = out.match(/HTTP (\d+)/)?.[1];
  return { voice, model, code, err: code === '200' ? null : out.slice(0, 400), voiceEcho: code==='200' ? (out.match(/"voice":\s*"([^"]+)"/)?.[1]) : null };
};
