"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useConversation } from "@elevenlabs/react";
import { TRANSCRIPT_SCRIPT, type Persona, type Provider } from "@/lib/data";
import type { Lang } from "@/lib/lang";
import type { CallState, SessionApi, SessionTurn } from "./types";
import { useElevenLabsMemory } from "@/lib/memory/use-elevenlabs-memory";
import { formatResumeUpdate } from "@/lib/conversations/resume";
import type { ConversationDetail } from "@/lib/conversations/types";
import { resolveElevenLabsAgentId } from "./elevenlabs-agent";
import { useXaiSession } from "./use-xai-session";
import { useOpenaiSession } from "./use-openai-session";
import { useGeminiSession } from "./use-gemini-session";
import { useCascadeSession } from "./use-cascade-session";
import { useFalSession } from "./use-fal-session";
import { useMoshiSession } from "./use-moshi-session";

const SCRIPT_TURNS: SessionTurn[] = TRANSCRIPT_SCRIPT.map((t, i) => ({
  id: `s${i}`,
  who: t.who,
  text: t.text,
}));

const LAST = TRANSCRIPT_SCRIPT.length - 1;

/** An earlier call's turns, shown above the new call's while it is being continued. */
function priorTurns(resume: ConversationDetail): SessionTurn[] {
  return resume.transcript.map((t, i) => ({ id: `h${i}`, who: t.who, text: t.text }));
}

function mockCaption(state: CallState): string {
  switch (state) {
    case "idle":
      return "press CALL to begin";
    case "ended":
      return "— call ended —";
    case "connecting":
      return "establishing session…";
    case "listening":
      return TRANSCRIPT_SCRIPT[LAST - 1].text;
    case "speaking":
      return TRANSCRIPT_SCRIPT[LAST].text;
    case "interrupted":
      return "… you interrupted";
  }
}

/**
 * Unified realtime session. `provider.engine` selects the engine:
 *   - undefined → the design's mock lifecycle (timers + TRANSCRIPT_SCRIPT)
 *   - "elevenlabs" → real conversation via `@elevenlabs/react`
 *   - "xai" → real Grok voice via a direct WebSocket (useXaiSession)
 *   - "openai" → real gpt-realtime voice via WebRTC (useOpenaiSession)
 *   - "gemini" → real Gemini Live voice via a direct WebSocket (useGeminiSession)
 *   - "fal" → full-duplex PersonaPlex via a direct WebSocket (useFalSession)
 *   - "moshi" → full-duplex PersonaPlex on the LOCAL MLX server (useMoshiSession)
 * All expose the same `SessionApi` so the UI is provider-agnostic.
 *
 * `useXaiSession` and `useOpenaiSession` share one interface, so the dispatcher
 * picks whichever is active as `custom` and routes every control through it.
 *
 * All real-engine hooks (`useConversation`, `useXaiSession`, `useOpenaiSession`)
 * are called unconditionally (rules of hooks) and stay inert until their engine
 * is selected and started.
 */
export function useRealtimeSession({
  provider,
  persona,
  lang = "en",
  lmModelId,
  voiceBargeIn,
  pushToTalk,
  resume = null,
  memoryEnabled = true,
}: {
  provider: Provider;
  persona?: Persona;
  /**
   * Session language. ElevenLabs routes it to a dedicated JA agent; xAI, OpenAI
   * and Gemini apply it through the prompt. Read when a call starts — changing
   * it mid-call needs a new session (see use-session-routing).
   */
  lang?: Lang;
  /** Cascade-only: overrides the catalog default LM model (from the Providers picker). */
  lmModelId?: string;
  /** OpenAI-only: let user speech interrupt the agent (settings INTERRUPTIONS toggle). */
  voiceBargeIn?: boolean;
  /** Cascade-only: only the Send button ends a turn (settings PUSH-TO-TALK toggle). */
  pushToTalk?: boolean;
  /**
   * ElevenLabs-only: an earlier call to continue. While idle its turns fill the
   * transcript; at CALL its tail goes to the agent as context. The caller arms
   * it only for the call's own persona on the ElevenLabs row.
   */
  resume?: ConversationDetail | null;
  /** ElevenLabs-only: long-term memory (the memory.recall tool). */
  memoryEnabled?: boolean;
}): SessionApi {
  const engine = provider.engine;
  const isReal = !!engine;

  const [callState, setCallState] = useState<CallState>(isReal ? "idle" : "listening");
  const [turns, setTurns] = useState<SessionTurn[]>(isReal ? [] : SCRIPT_TURNS);
  const [caption, setCaption] = useState<string>(
    isReal ? "press CALL to begin" : mockCaption("listening"),
  );
  const [muted, setMuted] = useState(false);
  const [elapsed, setElapsed] = useState(0);

  const stateRef = useRef(callState);
  stateRef.current = callState;
  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);
  const clearTimers = () => {
    timers.current.forEach(clearTimeout);
    timers.current = [];
  };

  // ── ElevenLabs real conversation ──────────────────────────────────────────
  const realPhase = useRef<"idle" | "active" | "ended">("idle");
  // mem0 long-term memory: recalled at CALL, injected at connect, ingested at end.
  const memory = useElevenLabsMemory();
  // Callbacks below outlive the render that created them; read the live object.
  const conversationRef = useRef<ReturnType<typeof useConversation> | null>(null);
  const conversation = useConversation({
    micMuted: muted,
    onConnect: ({ conversationId }: { conversationId: string }) => {
      memory.connected(conversationId, (text) =>
        conversationRef.current?.sendContextualUpdate(text),
      );
    },
    onDisconnect: () => memory.ended(),
    onMessage: (msg: { source?: string; message?: string }) => {
      const who = msg.source === "user" ? "user" : "agent";
      const text = msg.message ?? "";
      if (!text) return;
      setTurns((prev) => [...prev, { id: `r${prev.length}`, who, text }]);
      setCaption(text);
    },
    onError: () => {
      realPhase.current = "ended";
      setCallState("ended");
      setCaption("— connection error —");
    },
  });

  conversationRef.current = conversation;
  const { status, mode, isSpeaking, startSession, endSession } = conversation;

  // ── Custom real engines (own WebSocket / WebRTC, shared interface) ─────────
  const xai = useXaiSession(engine === "xai", persona, lang);
  const openai = useOpenaiSession(engine === "openai", persona, voiceBargeIn ?? false, lang);
  const gemini = useGeminiSession(engine === "gemini", persona, lang);
  const cascade = useCascadeSession(engine === "cascade", persona, lmModelId, pushToTalk ?? false);
  const fal = useFalSession(engine === "fal", persona);
  const moshi = useMoshiSession(engine === "moshi", persona);
  // Whichever custom engine is active owns the session; null ⇒ ElevenLabs/mock.
  const custom =
    engine === "xai"
      ? xai
      : engine === "openai"
        ? openai
        : engine === "gemini"
          ? gemini
          : engine === "cascade"
            ? cascade
            : engine === "fal"
              ? fal
              : engine === "moshi"
                ? moshi
                : null;

  // The active call state comes from whichever engine owns the session.
  const activeCallState: CallState = custom ? custom.callState : callState;

  // Derive real CallState from the conversation status/mode (ElevenLabs only).
  const prevStatusRef = useRef(status);
  useEffect(() => {
    const prev = prevStatusRef.current;
    prevStatusRef.current = status;
    if (engine !== "elevenlabs" || realPhase.current === "idle") return;
    // A call that drops on its own (remote hangup, network) never passes
    // through hangup() or onError, so mark it ended here. Only a transition
    // out of a live status counts: right after CALL the SDK still reports the
    // previous call's "disconnected" while realPhase is already "active".
    const live = prev === "connecting" || prev === "connected";
    if (live && (status === "disconnected" || status === "error")) {
      realPhase.current = "ended";
    }
    if (realPhase.current === "ended") {
      setCallState("ended");
      return;
    }
    if (status === "connecting") setCallState("connecting");
    else if (status === "error") setCallState("ended");
    else if (status === "disconnected") setCallState("ended");
    else if (status === "connected") {
      setCallState(mode === "speaking" || isSpeaking ? "speaking" : "listening");
      setCaption((c) => (c === "establishing session…" ? "listening…" : c));
    }
  }, [engine, status, mode, isSpeaking]);

  // ── Mock lifecycle ──────────────────────────────────────────────────────────
  // First-load drift: listening → speaking after 5s (matches the prototype).
  useEffect(() => {
    if (isReal) return;
    if (callState !== "listening") return;
    const t = setTimeout(() => setCallState("speaking"), 5000);
    return () => clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isReal]);

  // Caption sync for the mock engine.
  useEffect(() => {
    if (isReal) return;
    setCaption(mockCaption(callState));
  }, [isReal, callState]);

  // Elapsed ticker (all engines) — keyed off whichever engine owns the call.
  useEffect(() => {
    if (activeCallState === "idle" || activeCallState === "ended") {
      setElapsed(0);
      return;
    }
    const t = setInterval(() => setElapsed((e) => e + 1), 1000);
    return () => clearInterval(t);
  }, [activeCallState]);

  // Push mute into the active real engine. ElevenLabs only accepts setMuted once
  // connected (it throws "No active conversation" before startSession()); xAI
  // gates its own mic send, so it's always safe.
  useEffect(() => {
    if (engine === "elevenlabs" && status === "connected") conversation.setMuted(muted);
    else if (custom) custom.setMuted(muted);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [muted, engine, status]);

  // Reset to the active engine's initial state when the engine changes. End any
  // live ElevenLabs session we're navigating away from (xAI tears itself down
  // via its own `active` effect).
  useEffect(() => {
    clearTimers();
    try {
      if (realPhase.current === "active") endSession();
    } catch {
      // no active ElevenLabs session
    }
    realPhase.current = "idle";
    if (isReal) {
      setCallState("idle");
      setTurns([]);
      setCaption("press CALL to begin");
    } else {
      setCallState("listening");
      setTurns(SCRIPT_TURNS);
      setCaption(mockCaption("listening"));
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [engine]);

  // Arming or clearing a resume between calls shows (or drops) the earlier
  // call's turns. A call in progress keeps its transcript, and so does a
  // finished call: only turns this effect put up are taken down.
  const showingPriorRef = useRef(false);
  useEffect(() => {
    if (engine !== "elevenlabs" || realPhase.current === "active") return;
    if (resume) {
      showingPriorRef.current = true;
      setTurns(priorTurns(resume));
      setCaption("press CALL to continue");
    } else if (showingPriorRef.current) {
      showingPriorRef.current = false;
      setTurns([]);
      setCaption(stateRef.current === "ended" ? "— call ended —" : "press CALL to begin");
    }
  }, [engine, resume]);

  useEffect(() => () => clearTimers(), []);

  // ── Controls ────────────────────────────────────────────────────────────────
  const start = useCallback(() => {
    if (custom) {
      custom.start();
      return;
    }
    if (engine === "elevenlabs") {
      if (callState === "idle" || callState === "ended") {
        const agentId = resolveElevenLabsAgentId(persona?.id, lang);
        if (!agentId) {
          setCaption("— set NEXT_PUBLIC_ELEVENLABS_AGENT_ID —");
          return;
        }
        realPhase.current = "active";
        showingPriorRef.current = false;
        setTurns(resume ? priorTurns(resume) : []);
        setCallState("connecting");
        setCaption("establishing session…");
        const userId = memory.begin(persona?.id, lang, {
          memory: memoryEnabled,
          preface: resume ? formatResumeUpdate(resume, lang) : null,
        });
        startSession({ agentId, connectionType: "webrtc", userId } as Parameters<
          typeof startSession
        >[0]);
      } else {
        realPhase.current = "ended";
        endSession();
        setCallState("ended");
      }
      return;
    }
    // Mock
    clearTimers();
    if (callState === "idle" || callState === "ended") {
      setTurns(SCRIPT_TURNS);
      setCallState("connecting");
      timers.current.push(setTimeout(() => setCallState("listening"), 1400));
      timers.current.push(setTimeout(() => setCallState("speaking"), 3600));
    } else {
      setCallState("ended");
    }
  }, [
    engine,
    custom,
    callState,
    persona,
    lang,
    startSession,
    endSession,
    memory,
    resume,
    memoryEnabled,
  ]);

  const hangup = useCallback(() => {
    if (custom) {
      custom.stop();
      return;
    }
    if (engine === "elevenlabs") {
      realPhase.current = "ended";
      endSession();
    } else {
      clearTimers();
    }
    setCallState("ended");
  }, [engine, custom, endSession]);

  const interrupt = useCallback(() => {
    if (custom) {
      custom.interrupt();
      return;
    }
    if (stateRef.current !== "speaking") return;
    if (engine === "elevenlabs") {
      conversation.sendUserActivity();
      setCallState("interrupted");
      return;
    }
    clearTimers();
    setCallState("interrupted");
    timers.current.push(setTimeout(() => setCallState("listening"), 900));
  }, [engine, custom, conversation]);

  const toggleMute = useCallback(() => setMuted((m) => !m), []);

  // Manual end-of-turn — only the half-duplex cascade STT exposes one.
  const canSendTurn = engine === "cascade";
  const sendTurnEnabled = canSendTurn && cascade.sendTurnEnabled;
  const sendTurn = useCallback(() => {
    if (engine === "cascade") cascade.sendTurn();
  }, [engine, cascade]);

  // ── Volumes for the orb ───────────────────────────────────────────────────
  const getInputVolume = useCallback(() => {
    if (engine === "elevenlabs") {
      // Throws before startSession(); fall back to silence until connected.
      try {
        return conversation.getInputVolume();
      } catch {
        return 0;
      }
    }
    const s = stateRef.current;
    if (s === "listening" || s === "interrupted") {
      return 0.25 + 0.4 * Math.abs(Math.sin(performance.now() / 180));
    }
    return 0.04;
  }, [engine, conversation]);

  const getOutputVolume = useCallback(() => {
    if (engine === "elevenlabs") {
      try {
        return conversation.getOutputVolume();
      } catch {
        return 0;
      }
    }
    const s = stateRef.current;
    if (s === "speaking") {
      return 0.4 + 0.45 * Math.abs(Math.sin(performance.now() / 140));
    }
    return 0.04;
  }, [engine, conversation]);

  return useMemo<SessionApi>(
    () => ({
      callState: activeCallState,
      turns: custom ? custom.turns : turns,
      caption: custom ? custom.caption : caption,
      muted,
      elapsed,
      isReal,
      toggleMute,
      start,
      hangup,
      interrupt,
      sendTurn,
      canSendTurn,
      sendTurnEnabled,
      getInputVolume: custom ? custom.getInputVolume : getInputVolume,
      getOutputVolume: custom ? custom.getOutputVolume : getOutputVolume,
    }),
    [
      activeCallState,
      custom,
      turns,
      caption,
      muted,
      elapsed,
      isReal,
      toggleMute,
      start,
      hangup,
      interrupt,
      sendTurn,
      canSendTurn,
      sendTurnEnabled,
      getInputVolume,
      getOutputVolume,
    ],
  );
}

// Shared realtime types + small mapping helpers used across providers.

import type { AgentState } from "@/components/ui/orb";
import type { AgentState as BarState } from "@/components/ui/bar-visualizer";

export type CallState = "idle" | "connecting" | "listening" | "speaking" | "interrupted" | "ended";

export interface SessionTurn {
  id: string;
  who: "agent" | "user";
  text: string;
  live?: boolean;
}

// The unified surface every provider exposes to the UI. The UI never talks to a
// provider directly — it binds to this, and the active provider is swapped
// behind it (mock for the design's fake lifecycle, ElevenLabs for the real one).
export interface SessionApi {
  callState: CallState;
  turns: SessionTurn[];
  caption: string;
  muted: boolean;
  elapsed: number;
  isReal: boolean;
  toggleMute: () => void;
  start: () => void;
  hangup: () => void;
  interrupt: () => void;
  /** End the user's turn now (half-duplex cascade STT). No-op on full-duplex engines. */
  sendTurn: () => void;
  /** Whether this engine has a manual end-of-turn (only the cascade STT does). */
  canSendTurn: boolean;
  /** Whether the manual end-of-turn is currently usable while capture remains active. */
  sendTurnEnabled: boolean;
  getInputVolume: () => number;
  getOutputVolume: () => number;
}

export function isLive(s: CallState): boolean {
  return s !== "idle" && s !== "ended";
}

// CallState → ElevenLabs WebGL Orb agentState.
export function toOrbState(s: CallState): AgentState {
  switch (s) {
    case "speaking":
      return "talking";
    case "listening":
    case "interrupted":
      return "listening";
    case "connecting":
      return "thinking";
    default:
      return null;
  }
}

// CallState → BarVisualizer state.
export function toBarState(s: CallState): BarState {
  switch (s) {
    case "speaking":
      return "speaking";
    case "connecting":
      return "connecting";
    case "interrupted":
    case "listening":
      return "listening";
    default:
      return "initializing";
  }
}

"use client";

// Session routing: which transport + which language the session runs on, and
// what happens when either changes.
//
// - Japanese support has levels (Provider.ja): "agent" — a dedicated JA agent
//   per persona (ElevenLabs); "prompt" — Japanese through the instructions
//   (xAI, OpenAI, Gemini); absent — no Japanese path.
// - Failover is a transport concern, and a mid-call handover doesn't work
//   upstream. Any change that re-points the session at a different agent or
//   prompt (transport OR language) ends a live call and opens a NEW session;
//   the old one is never kept alive.
// - The two directions are separate, never one symmetric effect:
//   · Japanese picked on a transport with no JA path → the transport moves to
//     the last one a Japanese session ran on, else the best available (a
//     dedicated-agent transport first).
//   · A transport with no JA path picked while Japanese is on → the language
//     drops to EN immediately; the user's transport choice wins.

import { useCallback, useEffect, useRef, useState } from "react";
import { PROVIDERS, type JaSupport, type Provider } from "@/lib/data";
import type { Lang } from "@/lib/lang";
import { isLive, type SessionApi } from "@/lib/realtime/types";

/** Why the session was re-routed — drives the notice copy. */
export type RouteKind = "failover" | "downgrade" | "switch" | "unavailable";

export interface RouteNotice {
  kind: RouteKind;
  /** "switching" while a live call is being replaced; "done" once settled. */
  phase: "switching" | "done";
  /** Whether a live call was replaced (vs. a change made while idle). */
  live: boolean;
  from: string;
  to: string;
  lang: Lang;
  /** How the target transport speaks Japanese (undefined ⇒ it doesn't). */
  level?: JaSupport;
}

export interface SessionRouting {
  lang: Lang;
  provider: Provider;
  notice: RouteNotice | null;
  /** True while a replaced live call is waiting to be reopened. */
  restartPending: boolean;
  changeLang: (next: Lang, session: SessionApi) => void;
  changeProvider: (next: Provider, session: SessionApi) => void;
  /**
   * Move to an exact (transport, language) pair, e.g. to continue a stored call
   * where it ran. The pair must be valid (Japanese only on a JA transport).
   */
  routeTo: (provider: Provider, lang: Lang, session: SessionApi) => void;
  /** Called by useRestartAfterRoute once the new session has been opened (or abandoned). */
  settleRestart: () => void;
}

// Give the old session a beat to release the socket/mic before the new one
// opens. Not a correctness guard: each engine hook tags its setup with a
// per-start attempt token, so setup still in flight from the replaced call
// backs off on its own however late it resolves.
const RESTART_DELAY_MS = 600;
const NOTICE_MS = { live: 5600, idle: 4200 };

/** The best available JA transport: a dedicated-agent one first, then prompt-level. */
export function bestJaProvider(): Provider | undefined {
  return PROVIDERS.find((p) => p.ja === "agent") ?? PROVIDERS.find((p) => p.ja === "prompt");
}

export function useSessionRouting(): SessionRouting {
  const [lang, setLang] = useState<Lang>("en");
  const [provider, setProvider] = useState<Provider>(PROVIDERS[0]);
  const [notice, setNotice] = useState<RouteNotice | null>(null);
  const [restartPending, setRestartPending] = useState(false);
  // Last transport a Japanese session actually ran on — the preferred failover
  // target. Null until then, so the first failover goes to the best available.
  const lastJaRef = useRef<string | null>(null);
  const clearRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const showNotice = useCallback((next: RouteNotice | null, clearAfterMs?: number) => {
    if (clearRef.current) clearTimeout(clearRef.current);
    clearRef.current = null;
    setNotice(next);
    if (next && clearAfterMs) clearRef.current = setTimeout(() => setNotice(null), clearAfterMs);
  }, []);
  useEffect(
    () => () => {
      if (clearRef.current) clearTimeout(clearRef.current);
    },
    [],
  );

  // The UI mirrors the session language (font fallback, CJK line-breaking,
  // screen-reader voice all key off the document language).
  useEffect(() => {
    document.documentElement.lang = lang;
  }, [lang]);

  // Apply a new (transport, language) pair. `kind` names why, for the notice.
  const route = useCallback(
    (next: { provider: Provider; lang: Lang }, kind: RouteKind, session: SessionApi) => {
      const live = isLive(session.callState);
      const info: RouteNotice = {
        kind,
        live,
        phase: live ? "switching" : "done",
        from: provider.name,
        to: next.provider.name,
        lang: next.lang,
        level: next.provider.ja,
      };
      setProvider(next.provider);
      setLang(next.lang);
      if (next.lang === "ja" && next.provider.ja) lastJaRef.current = next.provider.id;

      if (live) {
        // Hang up the old session; useRestartAfterRoute opens the new one.
        session.hangup();
        setRestartPending(true);
        showNotice(info);
        return;
      }
      // Nothing to tear down. A plain switch needs no explanation; the forced
      // ones (failover / downgrade) do.
      if (kind === "switch") showNotice(null);
      else showNotice(info, NOTICE_MS.idle);
    },
    [provider, showNotice],
  );

  const changeLang = useCallback(
    (nextLang: Lang, session: SessionApi) => {
      if (nextLang === lang) return;
      if (nextLang === "ja" && !provider.ja) {
        const target =
          PROVIDERS.find((p) => p.id === lastJaRef.current && p.ja) ?? bestJaProvider();
        if (!target) {
          showNotice(
            { kind: "unavailable", phase: "done", live: false, from: "", to: "", lang },
            NOTICE_MS.idle,
          );
          return;
        }
        route({ provider: target, lang: "ja" }, "failover", session);
        return;
      }
      // Same transport, different agent or prompt.
      route({ provider, lang: nextLang }, "switch", session);
    },
    [lang, provider, route, showNotice],
  );

  const changeProvider = useCallback(
    (nextProvider: Provider, session: SessionApi) => {
      if (nextProvider.id === provider.id) return;
      if (lang === "ja" && !nextProvider.ja) {
        route({ provider: nextProvider, lang: "en" }, "downgrade", session);
        return;
      }
      route({ provider: nextProvider, lang }, "switch", session);
    },
    [lang, provider, route],
  );

  const routeTo = useCallback(
    (nextProvider: Provider, nextLang: Lang, session: SessionApi) => {
      if (nextProvider.id === provider.id && nextLang === lang) return;
      route({ provider: nextProvider, lang: nextLang }, "switch", session);
    },
    [lang, provider, route],
  );

  const settleRestart = useCallback(() => {
    setRestartPending(false);
    setNotice((n) => {
      if (!n) return n;
      if (clearRef.current) clearTimeout(clearRef.current);
      clearRef.current = setTimeout(() => setNotice(null), NOTICE_MS.live);
      return { ...n, phase: "done" };
    });
  }, []);

  return {
    lang,
    provider,
    notice,
    restartPending,
    changeLang,
    changeProvider,
    routeTo,
    settleRestart,
  };
}

/**
 * Reopens the call after a route change replaced a live session: waits for the
 * old session to end, then starts the new one on the new transport/language.
 * If the user starts a call themselves in the meantime, the pending restart is
 * dropped rather than firing later.
 */
export function useRestartAfterRoute(session: SessionApi, routing: SessionRouting) {
  const { restartPending, settleRestart } = routing;
  const startRef = useRef(session.start);
  startRef.current = session.start;
  const sawEndedRef = useRef(false);
  const live = isLive(session.callState);

  useEffect(() => {
    if (!restartPending) {
      sawEndedRef.current = false;
      return;
    }
    if (live) {
      // Still the old call winding down — or, once it has ended, a call the
      // user started on their own: that one supersedes the pending restart.
      if (sawEndedRef.current) settleRestart();
      return;
    }
    sawEndedRef.current = true;
    const timer = setTimeout(() => {
      startRef.current();
      settleRestart();
    }, RESTART_DELAY_MS);
    return () => clearTimeout(timer);
  }, [restartPending, live, settleRestart]);
}

"use client";

// Conversation history for the Conversations view: the visitor's stored calls
// (paged) and the one selected for reading. Loaded when the view mounts, so the
// list is fresh each visit; ElevenLabs needs a minute after hangup before a
// call is listed.

import { useCallback, useEffect, useRef, useState } from "react";
import {
  HistoryError,
  fetchConversationDetail,
  fetchConversationPage,
} from "@/lib/conversations/client";
import type { ConversationDetail, ConversationSummary } from "@/lib/conversations/types";
import { getMemoryUserId } from "@/lib/memory/user-id";

/** Why a load failed, in terms the view can phrase: missing key, or anything else. */
export type HistoryFailure = "unconfigured" | "failed";

export interface ConversationsState {
  items: ConversationSummary[];
  loading: boolean;
  failure: HistoryFailure | null;
  hasMore: boolean;
  loadMore: () => void;
  reload: () => void;
  selectedId: string | null;
  select: (id: string) => void;
  detail: ConversationDetail | null;
  detailLoading: boolean;
  detailFailure: HistoryFailure | null;
}

function failureOf(err: unknown): HistoryFailure | null {
  if (err instanceof DOMException && err.name === "AbortError") return null;
  return err instanceof HistoryError && err.status === 503 ? "unconfigured" : "failed";
}

function useConversationList() {
  const [items, setItems] = useState<ConversationSummary[]>([]);
  const [cursor, setCursor] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [failure, setFailure] = useState<HistoryFailure | null>(null);
  const abortRef = useRef<AbortController | null>(null);

  const load = useCallback((from: string | null) => {
    abortRef.current?.abort();
    const ctrl = new AbortController();
    abortRef.current = ctrl;
    setLoading(true);
    setFailure(null);
    fetchConversationPage(getMemoryUserId(), from, ctrl.signal)
      .then((page) => {
        setItems((prev) => (from ? [...prev, ...page.items] : page.items));
        setCursor(page.nextCursor);
        setLoading(false);
      })
      .catch((err: unknown) => {
        const f = failureOf(err);
        if (f === null) return; // superseded by a newer load
        setFailure(f);
        setLoading(false);
      });
  }, []);

  useEffect(() => {
    load(null);
    return () => abortRef.current?.abort();
  }, [load]);

  return {
    items,
    loading,
    failure,
    hasMore: cursor !== null,
    loadMore: () => cursor && !loading && load(cursor),
    reload: () => load(null),
  };
}

function useConversationDetail(selectedId: string | null) {
  const cache = useRef(new Map<string, ConversationDetail>());
  const [detail, setDetail] = useState<ConversationDetail | null>(null);
  const [loading, setLoading] = useState(false);
  const [failure, setFailure] = useState<HistoryFailure | null>(null);
  // Bumped to fetch the selected transcript again after a failure: the id
  // alone doesn't change, so the effect would not rerun.
  const [attempt, setAttempt] = useState(0);

  useEffect(() => {
    if (!selectedId) return;
    const hit = cache.current.get(selectedId);
    setDetail(hit ?? null);
    setFailure(null);
    setLoading(!hit);
    if (hit) return;
    const ctrl = new AbortController();
    fetchConversationDetail(getMemoryUserId(), selectedId, ctrl.signal)
      .then((d) => {
        cache.current.set(d.id, d);
        setDetail(d);
        setLoading(false);
      })
      .catch((err: unknown) => {
        const f = failureOf(err);
        if (f === null) return;
        setFailure(f);
        setLoading(false);
      });
    return () => ctrl.abort();
  }, [selectedId, attempt]);

  const retry = useCallback(() => setAttempt((n) => n + 1), []);
  return { detail, loading, failure, retry };
}

export function useConversations(initialId: string | null = null): ConversationsState {
  const list = useConversationList();
  const [selectedId, setSelectedId] = useState<string | null>(initialId);
  const { detail, loading, failure, retry } = useConversationDetail(selectedId);
  return {
    ...list,
    // REFRESH also retries a transcript that failed to load. A loaded one is
    // kept: a finished call's transcript does not change.
    reload: () => {
      list.reload();
      if (failure) retry();
    },
    selectedId,
    select: setSelectedId,
    detail,
    detailLoading: loading,
    detailFailure: failure,
  };
}

// Conversation history: the visitor's finished ElevenLabs calls, newest first.
//
// POST { userId, cursor? } → { items, nextCursor }. POST rather than GET keeps
// the visitor id out of URLs and logs. Dev only: ELEVENLABS_API_KEY from fnox.

import { listConversations } from "@/lib/conversations/elevenlabs-history";
import { fail, parseHistoryRequest, upstreamFailure } from "@/lib/conversations/route-helpers";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

// ElevenLabs cursors are opaque tokens; bound them so nothing odd reaches the URL.
const CURSOR_RE = /^[A-Za-z0-9_\-=.]{1,512}$/;

export async function POST(req: Request): Promise<Response> {
  const parsed = await parseHistoryRequest(req);
  if (!parsed.ok) return parsed.response;
  const { cursor } = parsed.body;
  if (cursor !== undefined && (typeof cursor !== "string" || !CURSOR_RE.test(cursor))) {
    return fail("cursor is malformed.", 400);
  }
  try {
    return Response.json(await listConversations(parsed.apiKey, parsed.userId, cursor));
  } catch (err) {
    return upstreamFailure(err);
  }
}

// One stored call with its transcript, for reading back or resuming.
//
// POST { userId } → ConversationDetail. A call that isn't the visitor's answers
// 404, the same as a missing one.

import { getConversation } from "@/lib/conversations/elevenlabs-history";
import { fail, parseHistoryRequest, upstreamFailure } from "@/lib/conversations/route-helpers";
import { isConversationId } from "@/lib/memory/ids";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

export async function POST(req: Request, ctx: { params: Promise<{ id: string }> }) {
  const { id } = await ctx.params;
  if (!isConversationId(id)) return fail("conversation id is malformed.", 400);
  const parsed = await parseHistoryRequest(req);
  if (!parsed.ok) return parsed.response;
  try {
    return Response.json(await getConversation(parsed.apiKey, parsed.userId, id));
  } catch (err) {
    return upstreamFailure(err);
  }
}

// Server-only: a visitor's stored ElevenLabs calls, mapped to history shapes.
//
// Every ElevenLabs session starts with the visitor's opaque memory id as its
// `userId`, and ElevenLabs records it on the conversation. The list filters on
// it upstream; the detail fetch checks it before returning a transcript.

import type { Lang } from "@/lib/lang";
import { agentPersona } from "@/lib/realtime/elevenlabs-agent";
import {
  ConversationError,
  fetchConversation,
  type StoredConversation,
  type TranscriptTurn,
} from "@/lib/memory/elevenlabs-conversation";
import type {
  ConversationDetail,
  ConversationPage,
  ConversationSummary,
  ConversationTurn,
} from "./types";

const CONVERSATIONS_URL = "https://api.elevenlabs.io/v1/convai/conversations";
const PAGE_SIZE = 30;
// Calls where the visitor never spoke are filtered out after fetching. A page
// made only of those would read as "no calls" with nothing to load more from,
// so keep paging until a page yields something, up to this bound.
const MAX_PAGES_PER_REQUEST = 5;
// Still running or not yet analysed: nothing worth reading back or resuming.
const UNFINISHED = ["initiated", "in-progress", "processing"];

/** One row of GET /v1/convai/conversations (summary_mode=include). */
interface ListedConversation {
  conversation_id: string;
  agent_id?: string;
  start_time_unix_secs?: number;
  call_duration_secs?: number;
  message_count?: number;
  user_message_count?: number;
  status?: string;
  transcript_summary?: string | null;
  call_summary_title?: string | null;
  main_language?: string | null;
}

interface ListResponse {
  conversations?: ListedConversation[];
  next_cursor?: string | null;
  has_more?: boolean;
}

function toLang(agentLang: Lang | undefined, mainLanguage?: string | null): Lang {
  if (agentLang) return agentLang;
  return mainLanguage === "ja" ? "ja" : "en";
}

// Expressive TTS directions such as "[softly]" open many agent lines. They are
// stage directions for the voice, not words, so history drops them.
const TTS_TAG_RE = /\[[^\]\n]{1,40}\]\s*/g;

function toTurns(transcript: TranscriptTurn[] | undefined): ConversationTurn[] {
  const out: ConversationTurn[] = [];
  for (const turn of transcript ?? []) {
    if (turn.role !== "user" && turn.role !== "agent") continue;
    const raw = turn.message?.trim() ?? "";
    const text = turn.role === "agent" ? raw.replace(TTS_TAG_RE, "").trim() : raw;
    if (text) out.push({ who: turn.role, text });
  }
  return out;
}

function summarize(row: ListedConversation): ConversationSummary {
  const mapped = row.agent_id ? agentPersona(row.agent_id) : undefined;
  return {
    id: row.conversation_id,
    personaId: mapped?.personaId,
    lang: toLang(mapped?.lang, row.main_language),
    title: row.call_summary_title?.trim() ?? "",
    summary: row.transcript_summary?.trim() ?? "",
    startedAt: row.start_time_unix_secs ?? 0,
    durationSecs: row.call_duration_secs ?? 0,
    messageCount: row.message_count ?? 0,
  };
}

async function fetchPage(apiKey: string, userId: string, cursor?: string): Promise<ListResponse> {
  const url = new URL(CONVERSATIONS_URL);
  url.searchParams.set("user_id", userId);
  url.searchParams.set("summary_mode", "include");
  url.searchParams.set("page_size", String(PAGE_SIZE));
  for (const s of UNFINISHED) url.searchParams.append("exclude_statuses", s);
  if (cursor) url.searchParams.set("cursor", cursor);

  const res = await fetch(url, { headers: { "xi-api-key": apiKey }, cache: "no-store" });
  if (!res.ok) {
    const detail = (await res.text()).slice(0, 300);
    throw new ConversationError(`ElevenLabs conversation list: ${detail}`, res.status);
  }
  return (await res.json()) as ListResponse;
}

/** The visitor's finished calls, newest first. Calls where they never spoke are left out. */
export async function listConversations(
  apiKey: string,
  userId: string,
  cursor?: string,
): Promise<ConversationPage> {
  const items: ConversationSummary[] = [];
  let next: string | null = cursor ?? null;
  for (let page = 0; page < MAX_PAGES_PER_REQUEST; page++) {
    const data = await fetchPage(apiKey, userId, next ?? undefined);
    for (const c of data.conversations ?? []) {
      if ((c.user_message_count ?? 0) > 0) items.push(summarize(c));
    }
    next = data.has_more ? (data.next_cursor ?? null) : null;
    if (items.length > 0 || !next) break;
  }
  return { items, nextCursor: next };
}

function detailOf(conv: StoredConversation): ConversationDetail {
  const transcript = toTurns(conv.transcript);
  return {
    ...summarize({
      conversation_id: conv.conversation_id,
      agent_id: conv.agent_id,
      start_time_unix_secs: conv.metadata?.start_time_unix_secs,
      call_duration_secs: conv.metadata?.call_duration_secs,
      message_count: transcript.length,
      transcript_summary: conv.analysis?.transcript_summary,
      call_summary_title: conv.analysis?.call_summary_title,
      main_language: conv.metadata?.main_language,
    }),
    transcript,
  };
}

/** One call with its transcript. Throws 404 for a missing call or one that isn't the visitor's. */
export async function getConversation(
  apiKey: string,
  userId: string,
  id: string,
): Promise<ConversationDetail> {
  const conv = await fetchConversation(apiKey, id);
  // Someone else's call answers exactly like a missing one, so ids can't be probed.
  if (!conv || conv.user_id !== userId) {
    throw new ConversationError(`conversation ${id} not found`, 404);
  }
  return detailOf(conv);
}

// Identifier shapes shared by the memory routes and the browser client.
//
// The memory user id is opaque and generated in the browser (see user-id.ts);
// it never carries a name or email. Both ids are validated server-side before
// they reach mem0 or ElevenLabs, so a malformed value can't widen a filter or
// alter an upstream URL.

export const MEMORY_USER_ID_PREFIX = "tsubaki-";

const MEMORY_USER_ID_RE = /^tsubaki-[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const CONVERSATION_ID_RE = /^conv_[A-Za-z0-9]+$/;

export function isMemoryUserId(value: unknown): value is string {
  return typeof value === "string" && MEMORY_USER_ID_RE.test(value);
}

export function isConversationId(value: unknown): value is string {
  return typeof value === "string" && CONVERSATION_ID_RE.test(value);
}

// The visitor's opaque memory id, created once per browser and kept in localStorage.
//
// It is the only identity the app has: no names, no emails. It is passed to
// ElevenLabs as the session `userId` (so stored conversations are attributable)
// and to mem0 as `user_id`. Clearing site data starts a fresh memory.

import { MEMORY_USER_ID_PREFIX, isMemoryUserId } from "./ids";

const KEY = "tsubaki.memory-user";

let fallback: string | undefined;

function mint(): string {
  return `${MEMORY_USER_ID_PREFIX}${crypto.randomUUID()}`;
}

export function getMemoryUserId(): string {
  try {
    const saved = localStorage.getItem(KEY);
    if (isMemoryUserId(saved)) return saved;
    const id = mint();
    localStorage.setItem(KEY, id);
    return id;
  } catch {
    // Storage blocked (private mode, policy): remember for this page load only.
    fallback ??= mint();
    return fallback;
  }
}

// Server-only: read a finished ElevenLabs conversation and turn it into mem0 input.
//
// ElevenLabs already stores every call. After hangup the conversation sits in
// "processing" for a while before its status becomes "done", so the ingest
// route polls until the call is final rather than trusting the browser's copy
// of the transcript.

import type { Mem0Message } from "./mem0-rest";

const CONVERSATIONS_URL = "https://api.elevenlabs.io/v1/convai/conversations";
const FINAL_STATUSES = new Set(["done", "failed"]);
const POLL_INTERVAL_MS = 3000;
const POLL_DEADLINE_MS = 90_000;

export interface TranscriptTurn {
  role?: string;
  message?: string | null;
}

export interface StoredConversation {
  conversation_id: string;
  agent_id?: string;
  agent_name?: string;
  status?: string;
  user_id?: string | null;
  transcript?: TranscriptTurn[];
  metadata?: {
    start_time_unix_secs?: number;
    call_duration_secs?: number;
    main_language?: string | null;
  } | null;
  analysis?: { transcript_summary?: string | null; call_summary_title?: string | null } | null;
}

export class ConversationError extends Error {
  constructor(
    message: string,
    readonly status: number,
  ) {
    super(message);
  }
}

/** The stored conversation, or null while ElevenLabs hasn't created the record yet. */
export async function fetchConversation(
  apiKey: string,
  id: string,
): Promise<StoredConversation | null> {
  const res = await fetch(`${CONVERSATIONS_URL}/${id}`, {
    headers: { "xi-api-key": apiKey },
    cache: "no-store",
  });
  if (res.status === 404) return null;
  if (!res.ok) {
    const detail = (await res.text()).slice(0, 300);
    throw new ConversationError(`ElevenLabs conversation ${id}: ${detail}`, res.status);
  }
  return (await res.json()) as StoredConversation;
}

/** Poll until the conversation reaches a final status, or give up at the deadline. */
export async function fetchFinishedConversation(
  apiKey: string,
  id: string,
): Promise<StoredConversation> {
  const deadline = Date.now() + POLL_DEADLINE_MS;
  for (;;) {
    const conv = await fetchConversation(apiKey, id);
    if (conv && FINAL_STATUSES.has(conv.status ?? "")) return conv;
    if (Date.now() + POLL_INTERVAL_MS > deadline) {
      const state = conv ? `still "${conv.status}"` : "not found";
      throw new ConversationError(`conversation ${id} ${state} after polling`, 504);
    }
    await new Promise((r) => setTimeout(r, POLL_INTERVAL_MS));
  }
}

/** Spoken turns only, in mem0's role vocabulary. Tool and system turns are dropped. */
export function toMem0Messages(conv: StoredConversation): Mem0Message[] {
  const out: Mem0Message[] = [];
  for (const turn of conv.transcript ?? []) {
    const content = turn.message?.trim();
    if (!content) continue;
    if (turn.role === "user") out.push({ role: "user", content });
    else if (turn.role === "agent") out.push({ role: "assistant", content });
  }
  return out;
}

// Catalog of fixed model ids for the realtime engines, edited as data in
// `config/realtime-models.json` — so bumping a provider's realtime model is a
// config edit, not a code change. Read by the client agent config
// (`openai-agent.ts`, which sends the model in `session.update`), the server
// mint route (`app/api/openai/token`, which scopes the ephemeral client secret
// to the same model), and the Providers UI label (`lib/data.ts`) — keeping all
// three in agreement by construction. The ElevenLabs TTS model is pushed to the
// platform agents by `scripts/elevenlabs/gen-agent-configs.ts` and shown in the
// same UI label, so the label can't drift from what the agents speak with.
// Client-safe: model ids only, no secrets.

import catalog from "@/config/realtime-models.json";
import type { Lang } from "@/lib/lang";

/** OpenAI realtime model — used for the ephemeral-token mint and `session.update`. */
export const OPENAI_REALTIME_MODEL: string = catalog.openai.model;

/** OpenAI input-audio transcription model paired with the realtime model. */
export const OPENAI_TRANSCRIPTION_MODEL: string = catalog.openai.transcriptionModel;

/** TTS model of the ElevenLabs platform agents, per session language. */
export const ELEVENLABS_TTS_MODEL: Record<Lang, string> = catalog.elevenlabs.ttsModel;

"use client";

import { useMemo, useState } from "react";
import { TopBar } from "./top-bar";
import { Sidebar, MobileDrawer, type NavId } from "./nav";
import { I18nContext } from "./i18n-context";
import { CallView } from "./call-view";
import { PersonasView } from "./personas-view";
import { ProvidersView } from "./providers-view";
import { ConversationsView } from "./conversations-view";
import { SettingsView } from "./settings-view";
import { TweaksPanel } from "./tweaks-panel";
import { RoutingNotice } from "./routing-notice";
import {
  PERSONAS,
  PROVIDERS,
  TOOLS_DEFAULT,
  resolvePersona,
  type Persona,
  type Provider,
  type Tool,
} from "@/lib/data";
import type { Lang } from "@/lib/lang";
import { makeT } from "@/lib/i18n";
import { useJaFonts } from "@/hooks/use-ja-fonts";
import { useRestartAfterRoute, useSessionRouting } from "@/hooks/use-session-routing";
import { useTweaks } from "@/hooks/use-tweaks";
import { useLmModel } from "@/hooks/use-lm-model";
import { useMediaQuery } from "@/hooks/use-media-query";
import { useNavKeys } from "@/hooks/use-nav-keys";
import { useResume, useSpendResumeAfterCall } from "@/hooks/use-resume";
import type { ConversationDetail } from "@/lib/conversations/types";
import { isLive } from "@/lib/realtime/types";
import { providerModelLabel, resolveLmModel } from "@/lib/realtime/lm-config";
import { providerExecLabel } from "@/lib/realtime/voice-config";
import { useRealtimeSession } from "@/lib/realtime/use-realtime-session";

export function AppShell() {
  const [tweaks, setTweak] = useTweaks();
  const [lmModelId, setLmModelId] = useLmModel();
  const [nav, setNav] = useState<NavId>("call");
  const [menuOpen, setMenuOpen] = useState(false);
  const [persona, setPersona] = useState<Persona>(PERSONAS[0]);
  // Transport + session language, and what happens when either changes
  // (JA failover, EN downgrade, new session on a live change).
  const routing = useSessionRouting();
  const { lang, provider } = routing;
  const [tools, setTools] = useState<Tool[]>(TOOLS_DEFAULT);
  const isMobile = useMediaQuery("(max-width: 760px)");
  // Bind the C/H/P/V/S section keys the sidebar advertises.
  useNavKeys(setNav);
  // A stored conversation the next call continues (ElevenLabs, same persona).
  const resume = useResume(provider, persona);
  const memoryEnabled = tools.find((tool) => tool.name === "memory.recall")?.on ?? true;

  const session = useRealtimeSession({
    provider,
    persona,
    lang,
    lmModelId,
    voiceBargeIn: tweaks.voiceBargeIn,
    pushToTalk: tweaks.pushToTalk,
    resume: resume.armed,
    memoryEnabled,
  });
  useSpendResumeAfterCall(resume, session.callState, routing.restartPending);
  // What the UI shows as the active model — tracks the LM picker for cascade.
  const providerModel = providerModelLabel(provider, lmModelId, lang);
  // Execution mode — for cascade, computed from the resolved backends.
  const providerExec = providerExecLabel(provider, resolveLmModel(lmModelId).backend);
  useRestartAfterRoute(session, routing);
  const setLang = (next: Lang) => routing.changeLang(next, session);
  const setProvider = (next: Provider) => routing.changeProvider(next, session);
  // CONTINUE on a stored call: its persona, on ElevenLabs, in the language it ran in.
  const continueConversation = (detail: ConversationDetail) => {
    const target = PERSONAS.find((p) => p.id === detail.personaId);
    const transport = PROVIDERS.find((p) => p.engine === "elevenlabs");
    if (!target || !transport || isLive(session.callState)) return;
    setPersona(target);
    routing.routeTo(transport, detail.lang, session);
    resume.select(detail);
    setNav("call");
  };
  // The persona as displayed in the session language (engines key off persona.id).
  const shown = resolvePersona(persona, lang);
  // The session language is also the UI locale.
  const t = useMemo(() => makeT(lang), [lang]);
  useJaFonts(tweaks.jaSans, tweaks.jaSerif);

  const sidebar = (onNav: (id: NavId) => void) => (
    <Sidebar
      nav={nav}
      setNav={onNav}
      persona={shown}
      provider={provider}
      providerModel={providerModel}
      providerExec={providerExec}
    />
  );

  return (
    <I18nContext.Provider value={t}>
      <div
        className={`tsubaki ${tweaks.dark ? "tsubaki-dark" : ""} ${isMobile ? "tb-mobile" : ""} ${tweaks.dock === "sidebar" && !isMobile ? "tb-tweaks-in-side" : ""} ${tweaks.dock === "top-right" && isMobile ? "tb-tweaks-in-bar" : ""}`}
        data-lang={lang}
      >
        <TopBar
          callState={session.callState}
          compact={isMobile}
          onMenu={isMobile ? () => setMenuOpen((o) => !o) : undefined}
          menuOpen={menuOpen}
        />
        <div className="tb-shell">
          {!isMobile && sidebar(setNav)}
          <main className="tb-main">
            <RoutingNotice notice={routing.notice} personaId={persona.id} />
            {nav === "call" && (
              <CallView
                tweaks={tweaks}
                session={session}
                persona={shown}
                provider={provider}
                providerModel={providerModel}
                lang={lang}
                setLang={setLang}
                compact={isMobile}
                tools={tools}
                resuming={resume.armed}
                onClearResume={resume.clear}
              />
            )}
            {nav === "conversations" && (
              <ConversationsView
                lang={lang}
                resumeId={resume.target?.id ?? null}
                callLive={isLive(session.callState)}
                onContinue={continueConversation}
                onClearResume={resume.clear}
              />
            )}
            {nav === "personas" && (
              <PersonasView
                persona={persona}
                setPersona={setPersona}
                provider={provider}
                lang={lang}
                setLang={setLang}
                accent={tweaks.accent}
              />
            )}
            {nav === "providers" && (
              <ProvidersView
                provider={provider}
                setProvider={setProvider}
                accent={tweaks.accent}
                lmModelId={lmModelId}
                setLmModelId={setLmModelId}
                lang={lang}
              />
            )}
            {nav === "settings" && (
              <SettingsView
                accent={tweaks.accent}
                lang={lang}
                setLang={setLang}
                tools={tools}
                setTools={setTools}
                muted={session.muted}
                onMutedChange={(m) => {
                  if (m !== session.muted) session.toggleMute();
                }}
                bargeIn={tweaks.voiceBargeIn}
                onBargeInChange={(v) => setTweak("voiceBargeIn", v)}
                pushToTalk={tweaks.pushToTalk}
                onPushToTalkChange={(v) => setTweak("pushToTalk", v)}
              />
            )}
          </main>
        </div>
        {/* Mobile reaches the same sections through a drawer hosting the
          desktop Sidebar. */}
        {isMobile && (
          <MobileDrawer open={menuOpen} onClose={() => setMenuOpen(false)}>
            {sidebar((id) => {
              setNav(id);
              setMenuOpen(false);
            })}
          </MobileDrawer>
        )}
        <TweaksPanel tweaks={tweaks} setTweak={setTweak} />
      </div>
    </I18nContext.Provider>
  );
}

