import { useT } from "./i18n-context";
import type { RouteNotice } from "@/hooks/use-session-routing";
import type { Translate } from "@/lib/i18n";

function noticeText(t: Translate, notice: RouteNotice, personaId: string): string {
  const { kind, phase, live, from, to, lang } = notice;
  if (kind === "unavailable") return t("route.unavailable");
  if (phase === "switching") return t(`route.${kind}.switching`, { from, to });
  // How the target transport speaks Japanese.
  const via =
    notice.level === "agent"
      ? t("route.via.agent", { agent: `tsubaki-${personaId}-ja` })
      : t("route.via.prompt");
  if (kind === "switch") {
    const langName = t(`lang.name.${lang}`);
    return t("route.switch.done", { to, lang: lang === "ja" ? `${langName} · ${via}` : langName });
  }
  return t(`route.${kind}.${live ? "done" : "idle"}`, { to, via });
}

/**
 * Session routing strip. Rendered once, above every page, so a language drop
 * triggered from Providers or Settings is explained where it happens.
 */
export function RoutingNotice({
  notice,
  personaId,
}: {
  notice: RouteNotice | null;
  personaId: string;
}) {
  const t = useT();
  if (!notice) return null;
  return (
    <div className="tb-route-slot">
      <div
        className={`tb-route-notice ${notice.phase} tb-route-${notice.kind}`}
        role="status"
        aria-live="polite"
      >
        {noticeText(t, notice, personaId)}
      </div>
    </div>
  );
}

import { Fragment } from "react";
import { Tag, Hr, Spec } from "./primitives";
import { useT } from "./i18n-context";
import { formatExec } from "@/lib/i18n";
import { PROVIDERS, type JaSupport, type Provider } from "@/lib/data";
import { lmModelsForEngine, providerModelLabel, resolveLmModel } from "@/lib/realtime/lm-config";
import {
  DEFAULT_STT_BACKEND_ID,
  DEFAULT_TTS_BACKEND_ID,
  providerExecLabel,
} from "@/lib/realtime/voice-config";
import type { CSSProperties } from "react";
import type { Lang } from "@/lib/lang";

/** Marks a JA-capable transport and how it gets there (solid: agent, dashed: prompt). */
function JaMark({ level }: { level: JaSupport }) {
  const t = useT();
  return (
    <span className={`tb-ja-mark tb-ja-mark-${level}`} title={t(`providers.jaMarkTitle.${level}`)}>
      {t(`providers.jaMark.${level}`)}
    </span>
  );
}

export function ProvidersView({
  provider,
  setProvider,
  accent,
  lmModelId,
  setLmModelId,
  lang,
}: {
  provider: Provider;
  setProvider: (p: Provider) => void;
  accent: string;
  lmModelId: string;
  setLmModelId: (id: string) => void;
  lang: Lang;
}) {
  const t = useT();
  // Surface the headline transport changes in the active-provider detail:
  // the cascade engine (STT→LM→TTS) and neural Silero VAD turn detection.
  const isCascade = provider.engine === "cascade";
  // The cascade's EXECUTION cell reflects the resolved backends, so it follows
  // the LM picker live (TTS/STT come from config/voice-models.json + env).
  const lmBackend = resolveLmModel(lmModelId).backend;

  return (
    <div className="tb-providers">
      <div className="tb-page-hd">
        <div>
          <div className="tb-h-eyebrow">{t("providers.eyebrow")}</div>
          <h1 className="tb-h1">{t("providers.title")}</h1>
          <p className="tb-lede">{t("providers.lede")}</p>
        </div>
        <div className="tb-page-hd-r">
          <Tag mono dot>
            {t("providers.autoFailover")}
          </Tag>
        </div>
      </div>

      <table className="tb-table">
        <thead>
          <tr>
            <th style={{ width: 32 }} />
            <th>{t("providers.th.vendor")}</th>
            <th>{t("providers.th.model")}</th>
            <th>{t("providers.th.exec")}</th>
            <th className="tb-th-note">{t("providers.th.notes")}</th>
          </tr>
        </thead>
        <tbody>
          {PROVIDERS.map((p) => {
            const on = provider.id === p.id;
            const radioStyle: CSSProperties | undefined = on
              ? { background: accent, borderColor: accent }
              : undefined;
            // Only engines with a multi-model catalog (cascade) get a picker inset;
            // single-model / unconfigurable providers render no inset.
            const models = lmModelsForEngine(p.engine);
            return (
              <Fragment key={p.id}>
                <tr className={on ? "on" : ""} onClick={() => setProvider(p)}>
                  <td className="tb-table-radio">
                    <span className={on ? "on" : ""} style={radioStyle} />
                  </td>
                  <td className="tb-table-vendor">
                    {p.name}
                    {p.ja && <JaMark level={p.ja} />}
                  </td>
                  <td className="tb-mono-num">{providerModelLabel(p, lmModelId, lang)}</td>
                  <td>
                    <Tag mono dot>
                      {formatExec(t, providerExecLabel(p, lmBackend))}
                    </Tag>
                  </td>
                  <td className="tb-table-note">{t(`prov.note.${p.id}`, null, p.note)}</td>
                </tr>
                {models.length > 1 && (
                  <tr className={`tb-prov-inset-row ${on ? "on" : ""}`}>
                    <td />
                    <td colSpan={4} className="tb-prov-inset">
                      <div className="tb-prov-inset-inner">
                        <span className="tb-prov-inset-l">{t("providers.lmModel")}</span>
                        <span className="tb-prov-models">
                          {models.map((m) => {
                            const sel = m.id === lmModelId;
                            return (
                              <button
                                key={m.id}
                                type="button"
                                className={`tb-prov-model ${sel ? "on" : ""}`}
                                style={sel ? { borderColor: accent, color: accent } : undefined}
                                aria-pressed={sel}
                                onClick={(e) => {
                                  e.stopPropagation();
                                  setLmModelId(m.id);
                                }}
                              >
                                {m.label}
                              </button>
                            );
                          })}
                        </span>
                      </div>
                    </td>
                  </tr>
                )}
              </Fragment>
            );
          })}
        </tbody>
      </table>

      <div className="tb-prov-detail">
        <Hr label={t("providers.active", { name: provider.name })} />
        <div className="tb-prov-specs">
          <Spec
            label={t("spec.engine")}
            value={provider.engine ? provider.engine.toUpperCase() : t("spec.engine.mock")}
            sub={
              isCascade
                ? "STT → LM → TTS"
                : t(provider.engine ? "spec.engine.native" : "spec.engine.preview")
            }
          />
          {isCascade ? (
            <Spec
              label={t("spec.voiceLegs")}
              value={`TTS ${DEFAULT_TTS_BACKEND_ID.toUpperCase()} · STT ${DEFAULT_STT_BACKEND_ID.toUpperCase()}`}
              sub="NEXT_PUBLIC_*_BACKEND · voice-models.json"
            />
          ) : (
            <Spec label={t("spec.codec")} value="opus 48k mono" sub={t("spec.codec.sub")} />
          )}
          <Spec
            label={t("spec.turn")}
            value={isCascade ? "Silero VAD" : t("spec.turn.server")}
            sub={t(isCascade ? "spec.turn.cascadeSub" : "spec.turn.serverSub")}
          />
          <Spec
            label={t("spec.language")}
            value={t(provider.ja ? "spec.language.both" : "spec.language.enOnly")}
            sub={t(`spec.language.sub.${provider.ja ?? "none"}`)}
          />
          <Spec label={t("spec.tools")} value={t("spec.tools.value")} sub={t("spec.tools.sub")} />
        </div>
      </div>
    </div>
  );
}

import { Btn } from "./primitives";
import { LangSwitch } from "./lang-switch";
import { useT } from "./i18n-context";
import { PERSONAS, resolvePersona, type Persona, type Provider } from "@/lib/data";
import type { Lang } from "@/lib/lang";

/** One persona, shown in the session language. */
function PersonaCard({
  p,
  index,
  lang,
  provider,
  on,
  accent,
  onSelect,
}: {
  p: Persona;
  index: number;
  lang: Lang;
  provider: Provider;
  on: boolean;
  accent: string;
  onSelect: (p: Persona) => void;
}) {
  const t = useT();
  const r = resolvePersona(p, lang);
  const ja = lang === "ja";
  // The cast JA voice belongs to the dedicated agent; on a prompt-level
  // transport the persona's usual voice speaks Japanese.
  const jaAgent = provider.ja === "agent";
  return (
    <div className={`tb-persona-card ${on ? "on" : ""}`} onClick={() => onSelect(p)}>
      <div className="tb-persona-top">
        <div className="tb-persona-num">{String(index + 1).padStart(2, "0")}</div>
        <div
          className="tb-persona-dot"
          style={{
            background: on ? accent : `color-mix(in srgb, ${accent} 26%, #000)`,
            boxShadow: on ? `0 0 0 4px color-mix(in srgb, ${accent} 22%, transparent)` : "none",
          }}
          role="img"
          aria-label={t(on ? "aria.activePersona" : "aria.inactivePersona")}
        />
      </div>
      <div className="tb-persona-name">
        {r.name}
        {ja && (
          <span className="tb-name-sub" lang="en">
            {p.name}
          </span>
        )}
      </div>
      <div className="tb-persona-accent">
        {r.accent} · {r.aspect}
      </div>
      <div className="tb-persona-traits">
        {r.traits.map((trait) => (
          <span key={trait} className="tb-trait">
            {trait}
          </span>
        ))}
      </div>
      <p className="tb-persona-desc">{r.desc}</p>
      {ja && r.greet && (
        <div className="tb-ja-greet">
          <span className="tb-ja-greet-l">{t("personas.firstMessage")}</span>
          <span className="tb-ja-greet-t">{r.greet}</span>
        </div>
      )}
      {ja && (
        <div className="tb-ja-support">
          <span className="tb-ja-support-l">
            {t(jaAgent ? "personas.jaAgent" : "personas.jaPrompt")}
          </span>
          <span className="tb-ja-support-v">
            {provider.name} · {jaAgent ? `tsubaki-${p.id}-ja` : t("personas.jaPromptValue")}
          </span>
        </div>
      )}
      <div className="tb-persona-foot">
        <span className="tb-mono-num">{r.rateLabel}</span>
        <span className="tb-mono-num">{ja && !jaAgent ? p.voice : r.voice}</span>
      </div>
    </div>
  );
}

export function PersonasView({
  persona,
  setPersona,
  provider,
  lang,
  setLang,
  accent,
}: {
  persona: Persona;
  setPersona: (p: Persona) => void;
  /** Active transport — decides whether Japanese uses a cast agent voice. */
  provider: Provider;
  lang: Lang;
  setLang: (lang: Lang) => void;
  accent: string;
}) {
  const t = useT();
  return (
    <div className="tb-personas">
      <div className="tb-page-hd">
        <div>
          <div className="tb-h-eyebrow">{t("personas.eyebrow")}</div>
          <h1 className="tb-h1">{t("personas.title")}</h1>
          <p className="tb-lede">{t("personas.lede")}</p>
        </div>
        <div className="tb-page-hd-r">
          <span className="tb-lang-field">
            <span className="tb-lang-field-l">{t("lang.label")}</span>
            <LangSwitch lang={lang} onChange={setLang} />
          </span>
          <Btn small>{t("personas.clone")}</Btn>
          <Btn small>{t("personas.import")}</Btn>
        </div>
      </div>

      <div className="tb-grid">
        {PERSONAS.map((p, i) => (
          <PersonaCard
            key={p.id}
            p={p}
            index={i}
            lang={lang}
            provider={provider}
            on={persona.id === p.id}
            accent={accent}
            onSelect={setPersona}
          />
        ))}

        <div className="tb-persona-card tb-persona-empty">
          <div className="tb-persona-num">+</div>
          <div className="tb-persona-name">{t("slot.name")}</div>
          <p className="tb-persona-desc">{t("slot.desc")}</p>
          <div className="tb-persona-drop">
            <span>{t("slot.drop")}</span>
          </div>
        </div>
      </div>
    </div>
  );
}

// Conversations: the visitor's stored ElevenLabs calls. Pick one to read it
// back; CONTINUE arms it so the next CALL picks the thread back up with the
// same persona (see hooks/use-resume.ts). ElevenLabs is the only transport
// that stores calls today, so it is the only one that can continue them.

import { useEffect, useRef } from "react";
import { useT } from "./i18n-context";
import { Btn, Tag } from "./primitives";
import { ConversationList } from "./conversation-list";
import { ConversationDetail } from "./conversation-detail";
import { useConversations, type HistoryFailure } from "@/hooks/use-conversations";
import type { ConversationDetail as Detail } from "@/lib/conversations/types";
import type { Lang } from "@/lib/lang";

function Status({ children }: { children: string }) {
  return <p className="tb-conv-status">{children}</p>;
}

function failureKey(f: HistoryFailure): string {
  return f === "unconfigured" ? "convs.unconfigured" : "convs.failed";
}

export function ConversationsView({
  lang,
  resumeId,
  callLive,
  onContinue,
  onClearResume,
}: {
  lang: Lang;
  /** The conversation the next call continues, if any (selected first on open). */
  resumeId: string | null;
  /** A call is in progress: continuing waits until it is hung up. */
  callLive: boolean;
  onContinue: (detail: Detail) => void;
  onClearResume: () => void;
}) {
  const t = useT();
  const convs = useConversations(resumeId);
  const listRef = useRef<HTMLDivElement>(null);
  const detailRef = useRef<HTMLDivElement>(null);
  // Narrow layouts stack the detail under the list. Once a picked call has
  // loaded (so there is something to scroll to), bring it into view.
  const scrollOnLoadRef = useRef(false);
  const select = (id: string) => {
    scrollOnLoadRef.current = true;
    convs.select(id);
  };
  const loadedId = convs.detail?.id;
  useEffect(() => {
    if (!scrollOnLoadRef.current || !loadedId) return;
    scrollOnLoadRef.current = false;
    const list = listRef.current?.getBoundingClientRect();
    const detail = detailRef.current;
    if (list && detail && detail.getBoundingClientRect().top >= list.bottom) {
      detail.scrollIntoView({ block: "start", behavior: "smooth" });
    }
  }, [loadedId]);
  const { items, loading, failure, detail, detailLoading, detailFailure } = convs;

  // The server drops calls where the visitor never spoke and stops after a
  // few upstream pages, so an empty page can still have older calls behind
  // it: keep LOAD MORE reachable instead of calling it the end of history.
  const emptyPage = items.length === 0 && convs.hasMore;
  let list;
  if (failure) list = <Status>{t(failureKey(failure))}</Status>;
  else if (loading && items.length === 0 && !convs.hasMore)
    list = <Status>{t("convs.loading")}</Status>;
  else if (items.length === 0 && !convs.hasMore) list = <Status>{t("convs.empty")}</Status>;
  else
    list = (
      <>
        {emptyPage && <Status>{t("convs.emptyPage")}</Status>}
        <ConversationList
          items={items}
          lang={lang}
          selectedId={convs.selectedId}
          onSelect={select}
          resumingId={resumeId}
          hasMore={convs.hasMore}
          loading={loading}
          onLoadMore={convs.loadMore}
        />
      </>
    );

  let pane;
  if (detailFailure) pane = <Status>{t(failureKey(detailFailure))}</Status>;
  else if (detailLoading) pane = <Status>{t("convs.loading")}</Status>;
  else if (detail)
    pane = (
      <ConversationDetail
        detail={detail}
        lang={lang}
        resuming={detail.id === resumeId}
        callLive={callLive}
        onContinue={() => onContinue(detail)}
        onClear={onClearResume}
      />
    );
  else pane = items.length > 0 ? <Status>{t("convs.pick")}</Status> : null;

  return (
    <div className="tb-convs">
      <div className="tb-page-hd">
        <div>
          <div className="tb-h-eyebrow">{t("convs.eyebrow")}</div>
          <h1 className="tb-h1">{t("convs.title")}</h1>
          <p className="tb-lede">{t("convs.lede")}</p>
        </div>
        <div className="tb-page-hd-r">
          <Tag mono dot>
            {t("convs.source")}
          </Tag>
          <Btn small onClick={convs.reload} disabled={loading}>
            {t("convs.refresh")}
          </Btn>
        </div>
      </div>
      <div className="tb-convs-body">
        <div className="tb-convs-list-col" ref={listRef}>
          {list}
        </div>
        <div className="tb-convs-detail-col" ref={detailRef}>
          {pane}
        </div>
      </div>
    </div>
  );
}

// Catalog of LM models + backends for the cascade (STT → LM → TTS) engine.
//
// Single source of truth, edited as data in `config/lm-models.json` — so changing
// which model the cascade uses is a config edit, not a code change, and there's no
// need to pull a live model list. Read by both the server route (`app/api/llm`,
// which resolves a backend's URL + secret env key) and the client agent config
// (`cascade-agent.ts`, which picks the model). Only env var *names* and public
// API URLs live here; secret values stay in fnox and are read server-side.

import catalog from "@/config/lm-models.json";
import type { Lang } from "@/lib/lang";
import { ELEVENLABS_TTS_MODEL } from "@/lib/realtime/realtime-model-config";

export interface LmBackendConfig {
  /** OpenAI-compatible chat-completions endpoint. */
  url: string;
  /** Name of the secret env var holding the bearer token (read server-side only).
   *  Empty string = keyless backend (local server); no Authorization header sent. */
  envKey: string;
  /** Send chat_template_kwargs.enable_thinking:false (reasoning models). Must be
   *  false for APIs that reject unknown fields (e.g. Mistral). */
  supportsThinking: boolean;
  /** Extra fields merged verbatim into the upstream chat-completions body — for
   *  backend-specific dialect knobs (e.g. Tinker's reasoning_effort). Cannot
   *  override model/messages/stream. */
  extraBody?: Record<string, unknown>;
}

export interface LmModel {
  /** Stable key used by `default` / a persona's `lmModelId`. */
  id: string;
  /** Human label (for docs / a future picker). */
  label: string;
  /** Backend id — a key of `backends`. */
  backend: string;
  /** Upstream model id (HF repo or Mistral model name). */
  model: string;
  temperature: number;
  maxTokens: number;
}

interface LmCatalog {
  default: string;
  backends: Record<string, LmBackendConfig>;
  models: LmModel[];
}

const CONFIG = catalog as unknown as LmCatalog;

export const LM_BACKENDS: Record<string, LmBackendConfig> = CONFIG.backends;
export const LM_MODELS: LmModel[] = CONFIG.models;

/** Look up a backend by id (undefined if not in the catalog). */
export function resolveLmBackend(id: string): LmBackendConfig | undefined {
  return LM_BACKENDS[id];
}

/** Resolve a model by id, falling back to the catalog `default`, then the first
 *  entry — so a stale/empty id never breaks a call. */
export function resolveLmModel(id?: string): LmModel {
  return (
    (id ? LM_MODELS.find((m) => m.id === id) : undefined) ??
    LM_MODELS.find((m) => m.id === CONFIG.default) ??
    LM_MODELS[0]
  );
}

/** The catalog default — the model every cascade persona uses unless it pins one. */
export const DEFAULT_LM_MODEL: LmModel = resolveLmModel(CONFIG.default);

/** Selectable LM models for a provider's engine. Only the cascade engine draws
 *  from the catalog; every other engine is a single fixed realtime model (so the
 *  Providers view shows no model picker for them). */
export function lmModelsForEngine(engine?: string): LmModel[] {
  return engine === "cascade" ? LM_MODELS : [];
}

/** MODEL label for a provider wherever the UI shows one (sidebar, call header,
 *  transcript drawer, providers table). Cascade reflects the *picked* catalog
 *  model — not the static string in lib/data.ts, which can't know the runtime
 *  selection. ElevenLabs shows the TTS model of the active language's agents.
 *  Every other engine has a single fixed model. */
export function providerModelLabel(
  provider: { engine?: string; model: string },
  lmModelId: string | undefined,
  lang: Lang,
): string {
  switch (provider.engine) {
    case "cascade":
      return `cascade · ${resolveLmModel(lmModelId).id}`;
    case "elevenlabs":
      return `agents · ${ELEVENLABS_TTS_MODEL[lang]}`;
    default:
      return provider.model;
  }
}

