// Left pane of the Conversations view: stored calls, newest first.

import { useT } from "./i18n-context";
import { Btn } from "./primitives";
import { formatDuration, formatStartedAt, personaName } from "./conversation-format";
import type { ConversationSummary } from "@/lib/conversations/types";
import { LANG_LABEL, type Lang } from "@/lib/lang";

export function ConversationList({
  items,
  lang,
  selectedId,
  onSelect,
  resumingId,
  hasMore,
  loading,
  onLoadMore,
}: {
  items: ConversationSummary[];
  lang: Lang;
  selectedId: string | null;
  onSelect: (id: string) => void;
  /** The conversation armed to be continued, marked in the list. */
  resumingId: string | null;
  hasMore: boolean;
  loading: boolean;
  onLoadMore: () => void;
}) {
  const t = useT();
  return (
    <div className="tb-conv-list">
      {items.map((c) => (
        <button
          key={c.id}
          type="button"
          className={`tb-conv-item ${c.id === selectedId ? "on" : ""}`}
          aria-current={c.id === selectedId ? "true" : undefined}
          onClick={() => onSelect(c.id)}
        >
          <span className="tb-conv-item-hd">
            <span className="tb-conv-item-who">
              {personaName(c.personaId, lang) ?? t("convs.unknownPersona")} · {LANG_LABEL[c.lang]}
            </span>
            <span>{formatStartedAt(c.startedAt, lang)}</span>
          </span>
          <span className="tb-conv-item-title">{c.title || t("convs.untitled")}</span>
          <span className="tb-conv-item-ft">
            <span>
              {formatDuration(c.durationSecs)} · {t("transcript.turns", { n: c.messageCount })}
            </span>
            {c.id === resumingId && <span className="tb-conv-item-armed">{t("convs.armed")}</span>}
          </span>
        </button>
      ))}
      {hasMore && (
        <div className="tb-conv-more">
          <Btn small onClick={onLoadMore} disabled={loading}>
            {t(loading ? "convs.loading" : "convs.more")}
          </Btn>
        </div>
      )}
    </div>
  );
}

// Right pane of the Conversations view: one call read back, with CONTINUE.

import { useT } from "./i18n-context";
import { Btn, Hr, Tag } from "./primitives";
import { formatDuration, formatStartedAt, personaName } from "./conversation-format";
import type { ConversationDetail as Detail } from "@/lib/conversations/types";
import { LANG_LABEL, type Lang } from "@/lib/lang";

function noteKey(mapped: boolean, callLive: boolean, resuming: boolean): string {
  if (!mapped) return "convs.continueUnmapped";
  if (callLive && !resuming) return "convs.busy";
  return "convs.continueNote";
}

export function ConversationDetail({
  detail,
  lang,
  resuming,
  callLive,
  onContinue,
  onClear,
}: {
  detail: Detail;
  lang: Lang;
  /** Whether this conversation is the one the next call continues. */
  resuming: boolean;
  callLive: boolean;
  onContinue: () => void;
  onClear: () => void;
}) {
  const t = useT();
  const name = personaName(detail.personaId, lang);
  const who = name ?? t("convs.unknownPersona");
  return (
    <article className="tb-conv-detail">
      <Hr label={detail.title || t("convs.untitled")} />
      <div className="tb-conv-tags">
        <Tag mono>{who}</Tag>
        <Tag mono>{LANG_LABEL[detail.lang]}</Tag>
        <Tag mono>{formatStartedAt(detail.startedAt, lang)}</Tag>
        <Tag mono>{formatDuration(detail.durationSecs)}</Tag>
      </div>
      {detail.summary && <p className="tb-conv-summary">{detail.summary}</p>}

      <div className="tb-conv-actions">
        {resuming ? (
          <>
            <Tag accent dot>
              {t("convs.armed")}
            </Tag>
            <Btn small onClick={onClear}>
              {t("convs.clear")}
            </Btn>
          </>
        ) : (
          <Btn
            primary
            onClick={onContinue}
            disabled={!name || callLive || detail.transcript.length === 0}
          >
            {t("convs.continue")}
          </Btn>
        )}
        <span className="tb-conv-note">
          {t(noteKey(!!name, callLive, resuming), { name: who })}
        </span>
      </div>

      <Hr label={t("transcript.turns", { n: detail.transcript.length })} />
      <div className="tb-conv-transcript">
        {detail.transcript.map((turn, i) => (
          <div key={i} className={`tb-turn tb-turn-${turn.who}`}>
            <div className="tb-turn-hd">
              <span className="tb-turn-who">{turn.who === "user" ? t("transcript.you") : who}</span>
            </div>
            <div className="tb-turn-text">{turn.text}</div>
          </div>
        ))}
      </div>
    </article>
  );
}

