}
.tb-mobile-sheet {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--paper);
  border-top: 1px solid var(--line);
  transform: translateY(calc(100% - 32px));
  transition: transform 0.28s cubic-bezier(0.2, 0.7, 0.3, 1);
  z-index: 5;
  max-height: 70%;
