  flex-direction: column;
}
.tb-mobile-sheet.open {
  transform: translateY(0);
}
.tb-mobile-sheet-handle {
  text-align: center;
  font-size: 9px;
  letter-spacing: 0.16em;
  color: var(--ink-3);
  padding: 8px;
  border-bottom: 1px solid var(--hair);
