}
.tb-mobile-sheet-scroll {
  flex: 1 1 auto;
  min-height: 0;
}
.tb-mobile-sheet-scroll .tb-scroll-area {
  padding: 0;
}
.tb-mobile-sheet-body {
  padding: 14px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.tb-mobile .tb-persona-card {
  min-height: 160px;
  padding: 12px;
}
.tb-mobile .tb-h1 {
  font-size: 26px;
}
.tb-mobile .tb-page-hd {
  padding: 14px;
}
.tb-mobile .tb-lede {
  font-size: 11px;
}
.tb-mobile .tb-table {
  font-size: 10px;
}
.tb-mobile .tb-table td,
.tb-mobile .tb-table th {
  padding: 8px 10px;
}
.tb-mobile .tb-settings-grid {
  grid-template-columns: 1fr;
}
.tb-mobile .tb-settings-sec {
  padding: 14px;
}

/* Responsive overrides: the single desktop shell adapts to the mobile layout
   (the design's two artboards become one responsive app). Sections are reached
   through the drawer, so nothing is fixed to the bottom edge. */
.tb-mobile .tb-shell {
  grid-template-columns: 1fr;
}
.tb-mobile .tb-call {
