}
.tb-mobile .tb-prov-specs {
  grid-template-columns: 1fr 1fr;
}

/* ── Orb (custom CSS/SVG visualizer — mono + particles + states) ───────── */

@keyframes tb-orb-breath {
  0%,
  100% {
    transform: scale(0.96);
  }
  50% {
    transform: scale(1.04);
  }
}
@keyframes tb-orb-listen {
  0%,
  100% {
    transform: scale(0.99);
  }
  50% {
    transform: scale(1.02);
  }
}
@keyframes tb-orb-speak {
  0% {
    transform: scale(0.94) rotate(0deg);
  }
  25% {
    transform: scale(1.07) rotate(2deg);
  }
  50% {
    transform: scale(0.97) rotate(-1deg);
  }
  75% {
    transform: scale(1.05) rotate(1deg);
  }
  100% {
    transform: scale(0.94) rotate(0deg);
  }
}
@keyframes tb-orb-spin {
  from {
    transform: rotate(0);
  }
  to {
    transform: rotate(360deg);
  }
}
@keyframes tb-orb-spin-r {
  from {
    transform: rotate(360deg);
  }
  to {
    transform: rotate(0);
  }
}
@keyframes tb-orb-ring {
  0% {
    transform: scale(1);
    opacity: 0.6;
  }
  100% {
    transform: scale(1.6);
    opacity: 0;
  }
}
@keyframes tb-bar {
  0%,
  100% {
    transform: scaleY(0.25);
  }
  50% {
    transform: scaleY(1);
  }
}

.tb-orb {
  position: relative;
  display: inline-block;
  width: var(--tb-orb-size, 320px);
  height: var(--tb-orb-size, 320px);
  --tb-accent: #b0122f;
}
.tb-orb-core {
  width: 100%;
  height: 100%;
  position: relative;
}
.tb-orb[data-state="idle"] .tb-orb-core {
  animation: tb-orb-breath 6s ease-in-out infinite;
}
.tb-orb[data-state="listening"] .tb-orb-core {
  animation: tb-orb-listen 1.4s ease-in-out infinite;
}
.tb-orb[data-state="speaking"] .tb-orb-core {
  animation: tb-orb-speak 2.2s ease-in-out infinite;
}
.tb-orb[data-state="connecting"] .tb-orb-core {
  animation: tb-orb-breath 1.4s ease-in-out infinite;
}
.tb-orb[data-state="ended"] .tb-orb-core {
  filter: grayscale(1) opacity(0.45);
}

.tb-orb-ring {
  position: absolute;
  inset: 0;
  border: 1px solid currentColor;
  border-radius: 50%;
  pointer-events: none;
  opacity: 0;
}
.tb-orb[data-state="listening"] .tb-orb-ring,
.tb-orb[data-state="speaking"] .tb-orb-ring {
  animation: tb-orb-ring 2.4s ease-out infinite;
}
.tb-orb[data-state="speaking"] .tb-orb-ring-2 {
  animation-delay: 0.8s;
}
.tb-orb[data-state="speaking"] .tb-orb-ring-3 {
  animation-delay: 1.6s;
}

.tb-orb-mono {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  background: radial-gradient(circle at 30% 30%, #ffffff, #c4c0b6 30%, #2a2926 75%, #060604 100%);
  position: relative;
  overflow: hidden;
}
.tb-orb-mono::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background-image: repeating-linear-gradient(
    45deg,
    transparent 0 6px,
    rgba(0, 0, 0, 0.15) 6px 7px
  );
  mix-blend-mode: multiply;
}
.tb-orb-mono::after {
  content: "";
  position: absolute;
  inset: 8%;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.5);
  background: radial-gradient(circle at 40% 30%, rgba(255, 255, 255, 0.7), transparent 45%);
}
.tb-orb.dark .tb-orb-mono {
  background: radial-gradient(circle at 30% 30%, #f4f2ed, #5a574e 30%, #161513 75%, #000 100%);
}

.tb-orb-particle {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  position: relative;
  overflow: hidden;
  background: radial-gradient(circle at 50% 50%, rgba(0, 0, 0, 0.04), transparent 70%);
}
.tb-orb.dark .tb-orb-particle {
  background: radial-gradient(circle at 50% 50%, rgba(255, 255, 255, 0.06), transparent 70%);
}
.tb-orb-particle svg {
  width: 100%;
  height: 100%;
  display: block;
}

.tb-bars {
  display: flex;
  align-items: end;
  justify-content: center;
  gap: 4px;
  height: 28px;
  margin-top: 22px;
}
.tb-bars > i {
  display: block;
  width: 3px;
  height: 100%;
  background: currentColor;
  transform-origin: center bottom;
  animation: tb-bar 0.9s ease-in-out infinite;
}
.tb-bars > i:nth-child(1) {
  animation-delay: -0.12s;
}
.tb-bars > i:nth-child(2) {
  animation-delay: -0.36s;
}
.tb-bars > i:nth-child(3) {
  animation-delay: -0.06s;
}
.tb-bars > i:nth-child(4) {
  animation-delay: -0.48s;
}
.tb-bars > i:nth-child(5) {
  animation-delay: -0.2s;
}
.tb-bars > i:nth-child(6) {
  animation-delay: -0.62s;
}
.tb-bars > i:nth-child(7) {
  animation-delay: -0.32s;
}
.tb-bars > i:nth-child(8) {
  animation-delay: -0.5s;
}
.tb-bars > i:nth-child(9) {
  animation-delay: -0.18s;
}
.tb-bars > i:nth-child(10) {
  animation-delay: -0.42s;
}

/* Brutalist override for the ElevenLabs BarVisualizer bars. */
.tb-elbars {
  width: 212px;
  height: 28px;
  color: var(--ink);
}
.tb-elbars-viz {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: end;
  justify-content: center;
  gap: 4px;
  background: transparent !important;
  border-radius: 0 !important;
  padding: 0 !important;
  overflow: visible !important;
}
.tb-elbars-viz > div {
  max-width: 4px;
  min-width: 3px;
  border-radius: 0 !important;
  background: currentColor !important;
}
.tb-elbars-viz > div[data-highlighted="true"] {
  background: var(--accent) !important;
}

/* ── Tweaks panel (in-app preferences) ────────────────────────────────── */

/* Position (and the panel's height cap) comes from the dock classes in
   app/styles/tweaks-dock.css. */
.tb-tweaks-toggle {
  position: fixed;
  z-index: 2147483646;
  appearance: none;
  cursor: pointer;
  width: 40px;
  height: 40px;
  border: 1px solid var(--line);
  background: var(--paper);
  color: var(--ink);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 3px 3px 0 var(--line);
}
/* Touch screens keep :hover after a tap, which would leave the button inked. */
@media (hover: hover) {
  .tb-tweaks-toggle:hover {
    background: var(--ink);
    color: var(--paper);
  }
}
.tb-tweaks {
  position: fixed;
  z-index: 2147483646;
  width: 280px;
  background: var(--paper);
  color: var(--ink);
  border: 1px solid var(--line);
  box-shadow: 4px 4px 0 var(--line);
  font-family: var(--tb-mono);
  font-size: 11px;
}
.tb-tweaks-hd {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 12px;
  border-bottom: 1px solid var(--line);
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  font-weight: 600;
}
.tb-tweaks-x {
  appearance: none;
  border: 0;
  background: transparent;
  color: var(--ink-3);
  cursor: pointer;
  font-size: 14px;
  line-height: 1;
}
.tb-tweaks-x:hover {
  color: var(--ink);
}
.tb-tweaks-body {
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.tb-tweaks-sect {
  font-size: 9px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink-3);
}
.tb-tweaks-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
.tb-seg {
  display: flex;
  border: 1px solid var(--line);
}
.tb-seg button {
  appearance: none;
  flex: 1;
  border: 0;
  border-right: 1px solid var(--hair);
  background: var(--paper);
  color: var(--ink-2);
  font: inherit;
  font-size: 9px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 6px 4px;
  cursor: pointer;
}
.tb-seg button:last-child {
  border-right: 0;
}
.tb-seg button.on {
  background: var(--ink);
  color: var(--paper);
  font-weight: 600;
}
.tb-swatches {
  display: flex;
  gap: 6px;
}
.tb-swatch {
  appearance: none;
  width: 28px;
  height: 22px;
  border: 1px solid var(--line);
  cursor: pointer;
  padding: 0;
}
.tb-swatch.on {
  outline: 2px solid var(--ink);
  outline-offset: 1px;
}

/* ── Session language (EN / 日本語) ───────────────────────────────────────
   .tsubaki carries data-lang; Japanese typography cascades from it. */

.tb-lang-sw {
  display: inline-flex;
  border: 1px solid var(--hair);
}
.tb-lang-btn {
  appearance: none;
  white-space: nowrap;
  font: inherit;
  font-size: 9px;
  letter-spacing: 0.08em;
  line-height: 1;
  padding: 4px 7px;
  background: none;
  border: 0;
  color: var(--ink-3);
  cursor: pointer;
}
.tb-lang-btn + .tb-lang-btn {
  border-left: 1px solid var(--hair);
}
.tb-lang-btn.on {
  background: var(--ink);
  color: var(--bg);
}
.tb-lang-field {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-right: 4px;
}
.tb-lang-field-l {
  font-size: 9px;
  letter-spacing: 0.14em;
  color: var(--ink-3);
}

/* Persona cards in Japanese */
.tb-name-sub {
