  margin-bottom: 10px;
}
.tb-ja-greet-l {
  font-size: 10.5px;
  letter-spacing: 0.04em;
  color: var(--ink-3);
}
.tb-ja-greet-t {
  font-family: var(--tb-serif);
  font-size: 11.5px;
  line-height: 1.8;
  color: var(--ink-2);
}
.tb-ja-support {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  font-size: 10.5px;
  letter-spacing: 0.04em;
  margin-bottom: 8px;
}
.tb-ja-support-l {
  color: var(--ink-3);
  white-space: nowrap;
}
.tb-ja-support-v {
  color: var(--ink-2);
  text-align: right;
}

/* JA support level on a transport: dedicated agent (solid) vs prompt (dashed). */
.tb-ja-mark {
  white-space: nowrap;
