"use client";

// One OPENAI LIVE call's browser side: microphone, WebRTC peer connection,
// `oai-events` data channel, playback element and level analysers.
//
// Each call owns its own instance, so a call still closing gracefully (waiting
// for session.closed) can never touch the call that replaced it. The server
// creates the session (app/api/openai-live/session); the browser only carries
// the media and shows what it hears.
//
// Playback goes straight through an <audio> element so Chrome's echo canceller
// keeps the remote track as its reference; the output analyser reads the remote
// stream passively and is never connected to the speakers.

import type { Lang } from "@/lib/lang";
import { analyserLevel } from "./audio-level";

const ICE_GATHER_TIMEOUT_MS = 10_000;
const CLOSE_TIMEOUT_MS = 5000;

/** A data-channel event, loosely typed: only the fields the client reads. */
export interface LiveServerEvent {
  type: string;
  event_id?: string;
  delta?: string;
  start_ms?: number;
  end_ms?: number;
  reason?: string;
  delegation?: { id?: string };
  error?: { message?: string; code?: string | null };
}

export interface LiveStartParams {
  personaId?: string;
  lang: Lang;
  /** The visitor's memory id; null skips memory and storage. */
  userId: string | null;
  memory: boolean;
  /** A stored OPENAI LIVE call to continue. */
  resumeId: string | null;
}

export type LiveOpenResult =
  | { ok: true; callId: string | null; greeting: string }
  | { ok: false; caption: string }
  | { ok: false; stale: true };

export interface LiveConnectionHandlers {
  onEvent: (ev: LiveServerEvent) => void;
  /** The connection went away without session.closed. */
  onDrop: () => void;
}

function waitForIce(pc: RTCPeerConnection): Promise<void> {
  if (pc.iceGatheringState === "complete") return Promise.resolve();
  return new Promise((resolve) => {
    // Past the timeout, send what has been gathered; the server answer still works
    // with partial candidates on most networks.
    const timer = setTimeout(done, ICE_GATHER_TIMEOUT_MS);
    function done() {
      clearTimeout(timer);
      pc.removeEventListener("icegatheringstatechange", onState);
      resolve();
    }
    function onState() {
      if (pc.iceGatheringState === "complete") done();
    }
    pc.addEventListener("icegatheringstatechange", onState);
  });
}

export class LiveConnection {
  private pc: RTCPeerConnection | null = null;
  private dc: RTCDataChannel | null = null;
  private stream: MediaStream | null = null;
  private audio: HTMLAudioElement | null = null;
  private ctx: AudioContext | null = null;
  private inAnalyser: AnalyserNode | null = null;
  private outAnalyser: AnalyserNode | null = null;
  private inBuf: Float32Array<ArrayBuffer> | null = null;
  private outBuf: Float32Array<ArrayBuffer> | null = null;
  private disposed = false;
  private closing = false;
  private resolveClosed: (() => void) | null = null;
  private micEnabled = true;

  constructor(private readonly handlers: LiveConnectionHandlers) {}

  /** Connect. `isStale` reports a hang-up or a newer call; setup backs off when it does. */
  async open(params: LiveStartParams, isStale: () => boolean): Promise<LiveOpenResult> {
    const stale = () => this.disposed || isStale();

    try {
      this.stream = await navigator.mediaDevices.getUserMedia({
        audio: { channelCount: 1, echoCancellation: true, noiseSuppression: true, autoGainControl: true },
      });
    } catch {
      return { ok: false, caption: "— microphone permission denied —" };
    }
    if (stale()) return { ok: false, stale: true };
    this.applyMic();

    const ctx = new AudioContext();
    this.ctx = ctx;
    if (ctx.state === "suspended") await ctx.resume();
    if (stale()) return { ok: false, stale: true };
    this.inAnalyser = ctx.createAnalyser();
    this.inAnalyser.fftSize = 1024;
    ctx.createMediaStreamSource(this.stream).connect(this.inAnalyser);
    this.inBuf = new Float32Array(this.inAnalyser.fftSize);

    const pc = new RTCPeerConnection();
    this.pc = pc;
    const audio = document.createElement("audio");
    audio.autoplay = true;
    this.audio = audio;
    pc.ontrack = (e) => {
      const remote = e.streams[0] ?? new MediaStream([e.track]);
      audio.srcObject = remote;
      void audio.play().catch(() => {
        // Autoplay is allowed after the CALL click; nothing to recover here.
      });
      try {
        const out = ctx.createAnalyser();
        out.fftSize = 1024;
        ctx.createMediaStreamSource(remote).connect(out);
        this.outAnalyser = out;
        this.outBuf = new Float32Array(out.fftSize);
      } catch {
        // levels are best-effort
      }
    };
    pc.onconnectionstatechange = () => {
      if (pc.connectionState === "failed" || pc.connectionState === "closed") this.dropped();
    };
    this.stream.getTracks().forEach((t) => pc.addTrack(t, this.stream!));

    // The data channel must exist before the offer.
    const dc = pc.createDataChannel("oai-events");
    this.dc = dc;
    dc.onmessage = (m) => {
      if (this.disposed) return;
      let ev: LiveServerEvent;
      try {
        ev = JSON.parse(typeof m.data === "string" ? m.data : "") as LiveServerEvent;
      } catch {
        return;
      }
      if (ev.type === "session.closed") this.resolveClosed?.();
      this.handlers.onEvent(ev);
    };
    dc.onclose = () => this.dropped();

    let offerSdp: string | undefined;
    try {
      await pc.setLocalDescription(await pc.createOffer());
      await waitForIce(pc);
      offerSdp = pc.localDescription?.sdp;
    } catch {
      return { ok: false, caption: "— could not establish WebRTC session —" };
    }
    if (stale()) return { ok: false, stale: true };
    if (!offerSdp) return { ok: false, caption: "— could not establish WebRTC session —" };

    let data: { sdp?: string; callId?: string | null; greeting?: string; error?: string };
    try {
      const res = await fetch("/api/openai-live/session", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ ...params, sdp: offerSdp }),
      });
      data = (await res.json()) as typeof data;
      if (!res.ok) return { ok: false, caption: `— ${data.error ?? "session error"} —` };
    } catch {
      return { ok: false, caption: "— could not reach session endpoint —" };
    }
    if (stale()) {
      // The session exists upstream; close it rather than leave it billing.
      return { ok: false, stale: true };
    }
    if (!data.sdp) return { ok: false, caption: "— could not establish WebRTC session —" };
    try {
      await pc.setRemoteDescription({ type: "answer", sdp: data.sdp });
    } catch {
      return { ok: false, caption: "— could not establish WebRTC session —" };
    }
    return { ok: true, callId: data.callId ?? null, greeting: data.greeting ?? "" };
  }

  send(ev: Record<string, unknown>): void {
    const dc = this.dc;
    if (dc && dc.readyState === "open") dc.send(JSON.stringify(ev));
  }

  setMicEnabled(enabled: boolean): void {
    this.micEnabled = enabled;
    this.applyMic();
  }

  private applyMic(): void {
    // `enabled = false` sends silence: the session keeps running, as GPT-Live expects.
    this.stream?.getAudioTracks().forEach((t) => (t.enabled = this.micEnabled));
  }

  /** Silence playback locally (the model's speech keeps flowing; the analyser still hears it). */
  setOutputMuted(muted: boolean): void {
    if (this.audio) this.audio.muted = muted;
  }

  inputLevel(): number {
    return this.micEnabled ? analyserLevel(this.inAnalyser, this.inBuf) : 0;
  }

  outputLevel(): number {
    return analyserLevel(this.outAnalyser, this.outBuf);
  }

  /**
   * Hang up gracefully: session.close, then wait for session.closed (so the
   * server-side capture finalizes cleanly) or a timeout, then release.
   */
  async close(): Promise<void> {
    if (this.disposed || this.closing) return;
    this.closing = true;
    if (this.dc?.readyState === "open") {
      const closed = new Promise<void>((resolve) => {
        this.resolveClosed = resolve;
        setTimeout(resolve, CLOSE_TIMEOUT_MS);
      });
      this.send({ type: "session.close" });
      // Nothing more should reach the caller while the session drains.
      this.setMicEnabled(false);
      this.setOutputMuted(true);
      await closed;
    }
    this.dispose();
  }

  private dropped(): void {
    if (this.disposed || this.closing) return;
    this.handlers.onDrop();
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    try {
      this.dc?.close();
    } catch {
      // already closing
    }
    try {
      this.pc?.close();
    } catch {
      // already closing
    }
    this.stream?.getTracks().forEach((t) => t.stop());
    if (this.audio) this.audio.srcObject = null;
    void this.ctx?.close();
    this.dc = null;
    this.pc = null;
    this.stream = null;
    this.audio = null;
    this.ctx = null;
    this.inAnalyser = null;
    this.outAnalyser = null;
  }
}

input.content:
"use client";

// OPENAI LIVE engine: GPT-Live (full duplex) over WebRTC, with the session
// created by our server (app/api/openai-live/session). Same surface as the
// other custom engines, so useRealtimeSession dispatches to it uniformly.
//
// What differs from the Realtime engine (use-openai-session.ts):
//   - No turn events. Transcript deltas are grouped into turns by timing
//     (lib/conversations/live-transcript.ts), and "speaking" comes from the
//     output level, since GPT-Live has no end-of-response event.
//   - Full duplex: no half-duplex mic gating. The user can talk over the agent.
//   - The server stores the call and its transcript, and ingests it into mem0
//     (live-capture.ts); this hook never uploads a transcript.
//   - Each call is a LiveConnection of its own, so a call still closing never
//     touches the one that replaced it (a language change restarts this hook).

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { Persona } from "@/lib/data";
import type { Lang } from "@/lib/lang";
import type { ConversationDetail } from "@/lib/conversations/types";
import { appendTranscriptDelta, type LiveTurn } from "@/lib/conversations/live-transcript";
import { getMemoryUserId } from "@/lib/memory/user-id";
import { LiveConnection, type LiveServerEvent } from "./live-connection";
import { isLive, type CallState, type SessionTurn } from "./types";

// Output level above this counts as the agent speaking; below it for
// SPEAKING_HOLD_MS, the agent has stopped.
const SPEAKING_LEVEL = 0.04;
const SPEAKING_HOLD_MS = 600;
const MONITOR_MS = 100;
// A manual interrupt mutes playback until the agent goes quiet, at most this long.
const INTERRUPT_MAX_MS = 4000;

const INTERRUPT_INSTRUCTION =
  "The caller pressed interrupt. Stop speaking now and listen to what they say.";
const NO_BACKEND_REPLY =
  "No lookup is possible in this conversation. Answer briefly from what you already know.";

// Data-channel events that need no handling (acks, reflected state).
const IGNORED_EVENTS = new Set([
  "session.instructions.appended",
  "session.commentary.appended",
  "session.thinking.appended",
  "session.usage.updated",
  "session.updated",
]);

export interface OpenaiLiveSession {
  callState: CallState;
  turns: SessionTurn[];
  caption: string;
  start: () => void;
  stop: () => void;
  interrupt: () => void;
  setMuted: (muted: boolean) => void;
  getInputVolume: () => number;
  getOutputVolume: () => number;
}

export interface OpenaiLiveOptions {
  /** The memory.recall tool: recall before and ingest after the call (server-side). */
  memoryEnabled: boolean;
  /** A stored OPENAI LIVE call to continue, armed by useResume. */
  resume: ConversationDetail | null;
}

function priorTurns(resume: ConversationDetail | null): SessionTurn[] {
  return (resume?.transcript ?? []).map((t, i) => ({ id: `h${i}`, who: t.who, text: t.text }));
}

function liveTurns(turns: LiveTurn[]): SessionTurn[] {
  return turns.map((t, i) => ({ id: `l${i}`, who: t.who, text: t.text.trim(), live: i === turns.length - 1 }));
}

export function useOpenaiLiveSession(
  active: boolean,
  persona: Persona | undefined,
  lang: Lang,
  { memoryEnabled, resume }: OpenaiLiveOptions,
): OpenaiLiveSession {
  const [callState, setCallState] = useState<CallState>("idle");
  const [turns, setTurns] = useState<SessionTurn[]>([]);
  const [caption, setCaption] = useState("press CALL to begin");

  const connRef = useRef<LiveConnection | null>(null);
  const stateRef = useRef<CallState>("idle");
  stateRef.current = callState;
  const personaRef = useRef(persona);
  personaRef.current = persona;
  const langRef = useRef(lang);
  langRef.current = lang;
  const memoryRef = useRef(memoryEnabled);
  memoryRef.current = memoryEnabled;
  const resumeRef = useRef(resume);
  resumeRef.current = resume;
  const mutedRef = useRef(false);

  // The current call's transcript. Updated here, then handed to setTurns as a
  // value: setTurns updaters must stay pure (StrictMode runs them twice).
  const liveTurnsRef = useRef<LiveTurn[]>([]);
  const priorRef = useRef<SessionTurn[]>([]);
  const monitorRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const lastLoudRef = useRef(0);
  const interruptAtRef = useRef<number | null>(null);

  const stopMonitor = useCallback(() => {
    if (monitorRef.current) clearInterval(monitorRef.current);
    monitorRef.current = null;
    interruptAtRef.current = null;
  }, []);

  /** End the current call locally (dropped, closed by OpenAI, or setup failed). */
  const endCall = useCallback(
    (conn: LiveConnection, message: string) => {
      if (connRef.current !== conn) return;
      connRef.current = null;
      stopMonitor();
      conn.dispose();
      setCallState("ended");
      setCaption(message);
    },
    [stopMonitor],
  );

  // Speaking follows the output level: GPT-Live has no end-of-response event.
  const startMonitor = useCallback(
    (conn: LiveConnection) => {
      stopMonitor();
      monitorRef.current = setInterval(() => {
        if (connRef.current !== conn) return;
        const now = performance.now();
        if (conn.outputLevel() > SPEAKING_LEVEL) lastLoudRef.current = now;
        const speaking = now - lastLoudRef.current < SPEAKING_HOLD_MS;
        const interruptAt = interruptAtRef.current;
        if (interruptAt !== null) {
          if (speaking && now - interruptAt < INTERRUPT_MAX_MS) return;
          interruptAtRef.current = null;
          conn.setOutputMuted(false);
        }
        const next: CallState = speaking ? "speaking" : "listening";
        if (stateRef.current !== next) setCallState(next);
      }, MONITOR_MS);
    },
    [stopMonitor],
  );

  const handleEvent = useCallback(
    (conn: LiveConnection, greeting: string, ev: LiveServerEvent) => {
      if (connRef.current !== conn) return;
      switch (ev.type) {
        case "session.started":
          setCallState("listening");
          setCaption("listening…");
          // Startup input already carries the greeting; this asks for it on the
          // instruction channel, the one that keeps exact wording.
          if (greeting) {
            conn.send({
              type: "session.instructions.append",
              event_id: "greeting",
              delegation_id: null,
              content: greeting,
            });
          }
          startMonitor(conn);
          break;
        case "session.input_transcript.delta":
        case "session.output_transcript.delta": {
          const who = ev.type === "session.input_transcript.delta" ? "user" : "agent";
          const next = appendTranscriptDelta(liveTurnsRef.current, who, ev.delta ?? "", ev.start_ms, ev.end_ms);
          liveTurnsRef.current = next;
          setTurns([...priorRef.current, ...liveTurns(next)]);
          const latest = [...next].reverse().find((t) => t.who === who);
          if (latest) setCaption(latest.text.trim());
          break;
        }
        case "session.delegation.created":
          // Nothing is behind client delegation here; answer so the turn can't stall.
          if (ev.delegation?.id) {
            conn.send({
              type: "session.commentary.append",
              event_id: `no-backend-${ev.delegation.id}`,
              delegation_id: ev.delegation.id,
              content: NO_BACKEND_REPLY,
            });
          }
          break;
        case "session.closed":
          endCall(conn, "— call ended —");
          break;
        case "error":
          setCaption(`— ${ev.error?.message ?? "OpenAI error"} —`);
          break;
        default:
          if (!IGNORED_EVENTS.has(ev.type) && process.env.NODE_ENV !== "production") {
            console.debug("[openai-live] unhandled event", ev.type);
          }
          break;
      }
    },
    [endCall, startMonitor],
  );

  const start = useCallback(() => {
    if (isLive(stateRef.current)) return;
    const conn = new LiveConnection({
      onEvent: (ev) => handleEvent(conn, greetingRef.greeting, ev),
      onDrop: () => endCall(conn, "— connection error —"),
    });
    // Filled in once the server answers; events before that carry no greeting need.
    const greetingRef = { greeting: "" };
    connRef.current = conn;
    const prior = priorTurns(resumeRef.current);
