    () => () => {
      const conn = connRef.current;
      connRef.current = null;
      stopMonitor();
      if (conn) void conn.close();
    },
    [stopMonitor],
  );

  return useMemo<OpenaiLiveSession>(
    () => ({
      callState,
      turns,
      caption,
      start,
      stop,
      interrupt,
      setMuted,
      getInputVolume,
      getOutputVolume,
    }),
    [callState, turns, caption, start, stop, interrupt, setMuted, getInputVolume, getOutputVolume],
  );
}
`);
'ok'

