@import "tailwindcss";
@import "tw-animate-css";
@import "shadcn/tailwind.css";

@custom-variant dark (&:is(.dark *));

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --font-sans: var(--font-sans);
  --font-mono: var(--font-geist-mono);
  --font-heading: var(--font-sans);
  --color-sidebar-ring: var(--sidebar-ring);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar: var(--sidebar);
  --color-chart-5: var(--chart-5);
  --color-chart-4: var(--chart-4);
  --color-chart-3: var(--chart-3);
  --color-chart-2: var(--chart-2);
  --color-chart-1: var(--chart-1);
  --color-ring: var(--ring);
  --color-input: var(--input);
  --color-border: var(--border);
  --color-destructive: var(--destructive);
  --color-accent-foreground: var(--accent-foreground);
  --color-accent: var(--accent);
  --color-muted-foreground: var(--muted-foreground);
  --color-muted: var(--muted);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-secondary: var(--secondary);
  --color-primary-foreground: var(--primary-foreground);
  --color-primary: var(--primary);
  --color-popover-foreground: var(--popover-foreground);
  --color-popover: var(--popover);
  --color-card-foreground: var(--card-foreground);
  --color-card: var(--card);
  --radius-sm: calc(var(--radius) * 0.6);
  --radius-md: calc(var(--radius) * 0.8);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) * 1.4);
  --radius-2xl: calc(var(--radius) * 1.8);
  --radius-3xl: calc(var(--radius) * 2.2);
  --radius-4xl: calc(var(--radius) * 2.6);
}

:root {
  --background: oklch(1 0 0);
  --foreground: oklch(0.145 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.145 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.145 0 0);
  --primary: oklch(0.205 0 0);
  --primary-foreground: oklch(0.985 0 0);
  --secondary: oklch(0.97 0 0);
  --secondary-foreground: oklch(0.205 0 0);
  --muted: oklch(0.97 0 0);
  --muted-foreground: oklch(0.556 0 0);
  --accent: oklch(0.97 0 0);
  --accent-foreground: oklch(0.205 0 0);
  --destructive: oklch(0.577 0.245 27.325);
  --border: oklch(0.922 0 0);
  --input: oklch(0.922 0 0);
  --ring: oklch(0.708 0 0);
  --chart-1: oklch(0.87 0 0);
  --chart-2: oklch(0.556 0 0);
  --chart-3: oklch(0.439 0 0);
  --chart-4: oklch(0.371 0 0);
  --chart-5: oklch(0.269 0 0);
  --radius: 0.625rem;
  --sidebar: oklch(0.985 0 0);
  --sidebar-foreground: oklch(0.145 0 0);
  --sidebar-primary: oklch(0.205 0 0);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.97 0 0);
  --sidebar-accent-foreground: oklch(0.205 0 0);
  --sidebar-border: oklch(0.922 0 0);
  --sidebar-ring: oklch(0.708 0 0);
}

.dark {
  --background: oklch(0.145 0 0);
  --foreground: oklch(0.985 0 0);
  --card: oklch(0.205 0 0);
  --card-foreground: oklch(0.985 0 0);
  --popover: oklch(0.205 0 0);
  --popover-foreground: oklch(0.985 0 0);
  --primary: oklch(0.922 0 0);
  --primary-foreground: oklch(0.205 0 0);
  --secondary: oklch(0.269 0 0);
  --secondary-foreground: oklch(0.985 0 0);
  --muted: oklch(0.269 0 0);
  --muted-foreground: oklch(0.708 0 0);
  --accent: oklch(0.269 0 0);
  --accent-foreground: oklch(0.985 0 0);
  --destructive: oklch(0.704 0.191 22.216);
  --border: oklch(1 0 0 / 10%);
  --input: oklch(1 0 0 / 15%);
  --ring: oklch(0.556 0 0);
  --chart-1: oklch(0.87 0 0);
  --chart-2: oklch(0.556 0 0);
  --chart-3: oklch(0.439 0 0);
  --chart-4: oklch(0.371 0 0);
  --chart-5: oklch(0.269 0 0);
  --sidebar: oklch(0.205 0 0);
  --sidebar-foreground: oklch(0.985 0 0);
  --sidebar-primary: oklch(0.488 0.243 264.376);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.269 0 0);
  --sidebar-accent-foreground: oklch(0.985 0 0);
  --sidebar-border: oklch(1 0 0 / 10%);
  --sidebar-ring: oklch(0.556 0 0);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
  html {
    @apply font-sans;
  }
}

/* ─────────────────────────────────────────────────────────────────────────
   TSUBAKI — brutalist editorial styles (ported from the design bundle).
   Mono everywhere, 1px hairlines, zero radius, ALL-CAPS tracked labels.
   Scoped under .tsubaki. Latin fonts come from next/font (--font-plex-mono /
   --font-newsreader); the Japanese Noto families are self-hosted from
   Fontsource (imported in app/layout.tsx). All are surfaced here as
   --tb-mono / --tb-serif.
   ───────────────────────────────────────────────────────────────────────── */

:root {
  /* Family names declared by the Fontsource @font-face rules. */
  --font-noto-sans-jp: "Noto Sans JP";
  --font-noto-serif-jp: "Noto Serif JP";
  /* A Japanese face sits behind the Latin ones as a per-glyph fallback: Latin
     stays Plex Mono / Newsreader, kana and kanji fall through. Noto by default;
     --tb-ja-sans / --tb-ja-serif are set from Tweaks (hooks/use-ja-fonts.ts). */
  --tb-mono:
    var(--font-plex-mono), var(--tb-ja-sans, var(--font-noto-sans-jp)), ui-monospace, monospace;
  --tb-serif:
    var(--font-newsreader), var(--tb-ja-serif, var(--font-noto-serif-jp)), ui-serif, Georgia, serif;
}

.tsubaki {
  --bg: #ece9e1;
  --paper: #f4f2ed;
  --ink: #0a0a09;
  --ink-2: #4a4842;
  --ink-3: #8c8a82;
  --line: #0a0a09;
  --hair: rgba(10, 10, 9, 0.16);
  --hair-2: rgba(10, 10, 9, 0.08);
  --accent: #b0122f; /* camellia crimson (Tsubaki) — was burnt orange #c2410c */
  --accent-fg: #ffffff;

  width: 100%;
  height: 100%;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--tb-mono);
  font-size: 13px;
  line-height: 1.5;
  letter-spacing: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.tsubaki.tsubaki-dark {
  --bg: #0a0a09;
  --paper: #161513;
  --ink: #f4f2ed;
  --ink-2: #b8b5ac;
  --ink-3: #6a685f;
  --line: #f4f2ed;
  --hair: rgba(244, 242, 237, 0.22);
  --hair-2: rgba(244, 242, 237, 0.1);
}

/* hide scrollbars inside the app */
.tsubaki *::-webkit-scrollbar {
  width: 0;
  height: 0;
}
.tsubaki * {
  scrollbar-width: none;
}

/* ── Top bar ──────────────────────────────────────────────────────────── */

.tb-topbar {
  display: flex;
  align-items: center;
  gap: 24px;
  height: 48px;
  padding: 0 20px;
  border-bottom: 1px solid var(--line);
  background: var(--paper);
  flex: 0 0 auto;
}
.tb-brand {
  display: flex;
  align-items: baseline;
  gap: 8px;
  font-weight: 600;
  letter-spacing: 0.06em;
  font-size: 12px;
}
.tb-brand-mark {
  display: inline-block;
  width: 12px;
  height: 12px;
  background: var(--ink);
  position: relative;
}
.tb-brand-mark::after {
  content: "";
  position: absolute;
  width: 6px;
  height: 6px;
  background: var(--accent);
  top: 3px;
  left: 3px;
}
.tb-brand-name {
  letter-spacing: 0.14em;
}
.tb-brand-sub {
  color: var(--ink-3);
  font-weight: 400;
  letter-spacing: 0.06em;
  font-size: 10px;
}

.tb-topbar-status {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-left: auto;
  font-size: 10px;
  letter-spacing: 0.08em;
  color: var(--ink-2);
}
.tb-topbar-status > span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

/* ── Layout ───────────────────────────────────────────────────────────── */

.tb-shell {
  flex: 1 1 auto;
  min-height: 0;
  display: grid;
  grid-template-columns: 184px 1fr;
  background: var(--bg);
}
.tb-side {
  border-right: 1px solid var(--line);
  background: var(--paper);
  display: flex;
  flex-direction: column;
  padding: 18px 0 12px;
  gap: 2px;
  font-size: 11px;
}
.tb-side-eyebrow {
  font-size: 9px;
  letter-spacing: 0.12em;
  color: var(--ink-3);
  padding: 0 18px 10px;
}
.tb-nav-item {
  appearance: none;
  background: transparent;
  border: 0;
  text-align: left;
  color: var(--ink-2);
  font: inherit;
  cursor: pointer;
  padding: 8px 18px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  letter-spacing: 0.06em;
  border-left: 2px solid transparent;
  text-transform: uppercase;
}
.tb-nav-item:hover {
  background: var(--bg);
  color: var(--ink);
}
.tb-nav-item.on {
  background: var(--bg);
  color: var(--ink);
  border-left-color: var(--accent);
  font-weight: 500;
}
.tb-nav-key {
  color: var(--ink-3);
  font-size: 9px;
  padding: 1px 5px;
  border: 1px solid var(--hair);
}

.tb-side-foot {
  margin-top: auto;
  padding: 12px 18px;
  border-top: 1px solid var(--hair);
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-size: 10px;
  color: var(--ink-3);
  letter-spacing: 0.04em;
}
.tb-side-foot b {
  color: var(--ink);
  font-weight: 500;
}

.tb-main {
  min-width: 0;
  min-height: 0;
  overflow: auto;
  position: relative;
  display: flex;
  flex-direction: column;
}

/* ── Page header ──────────────────────────────────────────────────────── */

.tb-page-hd {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 24px;
  padding: 28px 28px 18px;
  border-bottom: 1px solid var(--line);
}
.tb-page-hd-r {
  display: flex;
  gap: 8px;
  flex: 0 0 auto;
}

.tb-h-eyebrow {
  font-size: 10px;
  letter-spacing: 0.16em;
  color: var(--ink-3);
  text-transform: uppercase;
}
.tb-h1 {
  font-family: var(--tb-serif);
  font-size: 44px;
  font-weight: 400;
  letter-spacing: -0.01em;
  margin: 4px 0 6px;
  line-height: 1;
  font-style: italic;
}
.tb-lede {
  font-size: 12px;
  color: var(--ink-2);
  max-width: 56ch;
  margin: 0;
}

/* ── Primitives ───────────────────────────────────────────────────────── */

.tb-btn {
  appearance: none;
  cursor: pointer;
  font: inherit;
  background: var(--paper);
  color: var(--ink);
  border: 1px solid var(--line);
  padding: 8px 14px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-size: 11px;
  font-weight: 500;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  transition:
    background 0.08s,
    color 0.08s,
    transform 0.04s;
  border-radius: 0;
}
.tb-btn:hover:not(:disabled) {
  background: var(--ink);
  color: var(--paper);
}
.tb-btn:active:not(:disabled) {
  transform: translate(1px, 1px);
}
.tb-btn-sm {
  padding: 6px 10px;
  font-size: 10px;
}
.tb-btn-on {
  background: var(--ink);
  color: var(--paper);
}
.tb-btn-primary {
  background: var(--accent);
  color: var(--accent-fg);
  border-color: var(--accent);
}
.tb-btn-primary:hover:not(:disabled) {
  background: var(--ink);
  color: var(--paper);
  border-color: var(--ink);
}
.tb-btn-danger {
  background: var(--paper);
  color: var(--ink);
  border-color: var(--line);
}
.tb-btn:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}
/* Primed: the expected next action — Send while LISTENING on a manual-turn
   (cascade) engine, where the user must commit their turn. Accent outline + a
   soft pulse so it reads as the thing to press. */
.tb-btn-primed:not(:disabled) {
  color: var(--accent);
  border-color: var(--accent);
  animation: tb-btn-primed 1.6s ease-in-out infinite;
}
.tb-btn-primed:not(:disabled):hover {
  background: var(--accent);
  color: var(--accent-fg);
  border-color: var(--accent);
}
@keyframes tb-btn-primed {
  0%,
  100% {
    box-shadow: 0 0 0 0 color-mix(in srgb, var(--accent) 45%, transparent);
  }
  60% {
    box-shadow: 0 0 0 5px color-mix(in srgb, var(--accent) 0%, transparent);
  }
}
@media (prefers-reduced-motion: reduce) {
  .tb-btn-primed:not(:disabled) {
    animation: none;
  }
}

.tb-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 10px;
  letter-spacing: 0.1em;
  padding: 3px 7px;
  border: 1px solid var(--hair);
  color: var(--ink-2);
  background: transparent;
  text-transform: uppercase;
  white-space: nowrap;
}
.tb-tag-mono {
  font-variant-numeric: tabular-nums;
}
.tb-tag-accent {
  color: var(--accent);
  border-color: var(--accent);
}
.tb-dot {
  display: inline-block;
  width: 6px;
  height: 6px;
  background: var(--accent);
  border-radius: 50%;
}

.tb-hr {
  border: 0;
  border-top: 1px solid var(--hair);
  margin: 14px 0;
}
.tb-hr-l {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 22px 0 12px;
}
.tb-hr-line {
  flex: 1 1 auto;
  height: 1px;
  background: var(--hair);
}
.tb-hr-label {
  font-size: 10px;
  letter-spacing: 0.14em;
  color: var(--ink-3);
}

.tb-spec {
  border: 1px solid var(--hair);
  padding: 12px 14px;
  background: var(--paper);
}
.tb-spec-l {
  font-size: 9px;
  letter-spacing: 0.14em;
  color: var(--ink-3);
}
.tb-spec-v {
  font-size: 13px;
  color: var(--ink);
  margin-top: 4px;
}
.tb-spec-s {
  font-size: 10px;
  color: var(--ink-3);
  margin-top: 2px;
}

.tb-label {
  font-size: 10px;
  letter-spacing: 0.12em;
  color: var(--ink-3);
  text-transform: uppercase;
}
.tb-label-n {
  color: var(--accent);
  margin-right: 6px;
}

.tb-mono-num {
  font-variant-numeric: tabular-nums;
  color: var(--ink-2);
}

/* ── Call view ────────────────────────────────────────────────────────── */

.tb-call {
  flex: 1 1 auto;
  min-height: 0;
  display: grid;
  grid-template-columns: 1fr auto;
  position: relative;
}
.tb-call-stage {
  position: relative;
  display: flex;
  flex-direction: column;
  padding: 28px 28px 24px;
  min-width: 0;
  min-height: 0;
  /* The meta row reacts to the stage's own width, not the viewport: the
     transcript column and the sidebar both eat into it. */
  container: call-stage / inline-size;
}

.tb-call-meta {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  padding-bottom: 16px;
  border-bottom: 1px dashed var(--hair);
  flex: 0 0 auto;
}
.tb-call-meta-l,
.tb-call-meta-r {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  min-width: 0;
}
/* Narrow stage: stack SESSION/VIA above LANGUAGE/PERSONA instead of letting
   the two halves collide or spill into the transcript column. A long
   transport · model label may then wrap inside its chip. */
@container call-stage (max-width: 760px) {
  .tb-call-meta {
    flex-direction: column;
    align-items: flex-start;
  }
  .tb-call-meta .tb-tag {
    white-space: normal;
    overflow-wrap: anywhere;
  }
}

.tb-call-body {
  flex: 1 1 auto;
  min-height: 0;
  display: grid;
  grid-template-rows: 1fr 1fr;
  gap: 0;
}

.tb-orb-area {
  min-height: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 16px 0;
  color: var(--ink);
  position: relative;
  container-type: size;
}
.tb-orb-area::before,
.tb-orb-area::after {
  content: "";
  position: absolute;
  width: 22px;
  height: 22px;
  border: 1px solid var(--hair);
}
.tb-orb-area::before {
  top: 8px;
  left: 8px;
  border-right: 0;
  border-bottom: 0;
}
.tb-orb-area::after {
  bottom: 8px;
  right: 8px;
  border-left: 0;
  border-top: 0;
}
.tb-orb-fit {
  width: min(100cqh - 80px, 100cqw - 32px, 320px);
  height: min(100cqh - 80px, 100cqw - 32px, 320px);
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  position: relative;
}
/* Manual-turn "hold" ring — a held, slowly-rotating dashed ring shown only while
   LISTENING on a half-duplex (cascade) engine, where the turn ends on SEND. Reads
   differently from the auto pulse rings, which would imply automatic end-of-turn. */
.tb-orb-hold {
  position: absolute;
  inset: -7%;
  border: 1.5px dashed var(--accent);
  border-radius: 50%;
  pointer-events: none;
  animation: tb-orb-hold 9s linear infinite;
}
@keyframes tb-orb-hold {
  0% {
    transform: rotate(0deg) scale(1);
    opacity: 0.7;
  }
  50% {
    transform: rotate(180deg) scale(1.04);
    opacity: 0.95;
  }
  100% {
    transform: rotate(360deg) scale(1);
    opacity: 0.7;
  }
}
@media (prefers-reduced-motion: reduce) {
  .tb-orb-hold {
    animation: none;
    opacity: 0.85;
  }
}
.tb-orb-fit > .tb-orb {
  --tb-orb-size: 100%;
}
.tb-gradient-orb-wrap,
.tb-gradient-orb {
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  position: relative;
  overflow: hidden;
}
.tb-gradient-orb canvas {
  width: 100% !important;
  height: 100% !important;
}

.tb-caption-area {
  min-height: 0;
  display: flex;
  border-top: 1px dashed var(--hair);
  padding-top: 8px;
}
.tb-caption-scroll {
  width: 100%;
  height: 100%;
}
.tb-caption-scroll .tb-scroll-area {
  display: flex;
  /* Transcript-style anchor: pin the top edge so streaming text only grows
     downward into empty space — centered text re-centers on every line wrap. */
  align-items: flex-start;
  justify-content: center;
  padding: 16px 28px;
}

.tb-call-state {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  margin-top: 8px;
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}
.tb-call-state-l {
  font-weight: 600;
  color: var(--ink);
}
.tb-call-state-sub {
  color: var(--ink-3);
  font-size: 10px;
  letter-spacing: 0.08em;
}
/* Manual-turn hint — silence gate is off on this engine, so the user ends the
   turn with SEND. Shown under the orb state while listening on cascade. */
.tb-call-manual-hint {
  margin-top: 6px;
  font-size: 9.5px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--accent);
  text-align: center;
}
.tb-call-state-dot {
  width: 8px;
  height: 8px;
  background: var(--ink-3);
  position: relative;
}
.tb-state-listening,
.tb-state-speaking,
.tb-state-connecting,
.tb-state-interrupted {
  background: var(--accent);
}
.tb-state-listening::before,
.tb-state-speaking::before,
.tb-state-connecting::before {
  content: "";
  position: absolute;
  inset: 0;
  background: var(--accent);
  animation: tb-orb-ring 1.6s ease-out infinite;
}
.tb-state-ended {
  background: var(--ink-3);
}

.tb-caption {
  display: flex;
  justify-content: center;
  align-items: baseline;
  gap: 6px;
  font-family: var(--tb-serif);
  font-style: italic;
  font-size: 19px;
  color: var(--ink);
  text-align: center;
  padding: 0;
  max-width: 60ch;
  animation: tb-caption-in 0.4s ease both;
}
@keyframes tb-caption-in {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.tb-caption-q {
  color: var(--accent);
  font-size: 28px;
  line-height: 0.6;
}
/* Streamed caption chunks — each appended token group fades in as one unit.
   Opacity-only: transforms don't apply to inline boxes, and inline-block
   would stop multi-word chunks from wrapping mid-chunk. */
.tb-stream-chunk {
  animation: tb-stream-chunk-in 0.25s ease-out both;
}
@keyframes tb-stream-chunk-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@media (prefers-reduced-motion: reduce) {
  .tb-stream-chunk {
    animation: none;
  }
}
.tb-caption-t {
  text-wrap: pretty;
}

.tb-controls {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-top: 0;
  padding-top: 18px;
  border-top: 1px solid var(--hair);
  flex-wrap: wrap;
  flex: 0 0 auto;
}

.tb-transcript {
  width: 0;
  border-left: 1px solid var(--line);
  background: var(--paper);
  overflow: hidden;
  transition: width 0.24s ease;
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
}
.tb-transcript.open {
  width: 340px;
}
.tb-transcript-hd {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 16px;
  border-bottom: 1px solid var(--hair);
  font-size: 10px;
  letter-spacing: 0.12em;
  color: var(--ink-3);
  flex: 0 0 auto;
}
.tb-h-meta {
  color: var(--ink-3);
}
.tb-transcript-scroll {
  flex: 1 1 auto;
  min-height: 0;
}
.tb-transcript-scroll .tb-scroll-area {
  padding: 0;
}
.tb-transcript-body {
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.tb-turn {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.tb-turn-hd {
  display: flex;
  justify-content: space-between;
  font-size: 9px;
  letter-spacing: 0.1em;
  color: var(--ink-3);
  text-transform: uppercase;
}
.tb-turn-who {
  color: var(--ink);
  font-weight: 500;
}
.tb-turn-user .tb-turn-who {
  color: var(--accent);
}
.tb-turn-text {
  font-family: var(--tb-serif);
  font-style: italic;
  font-size: 15px;
  color: var(--ink);
  text-wrap: pretty;
}
.tb-turn-user .tb-turn-text {
  color: var(--ink-2);
}
.tb-turn-live .tb-turn-text {
  min-height: 24px;
}
.tb-cursor {
  display: inline-block;
  width: 8px;
  height: 16px;
  background: var(--accent);
  vertical-align: -3px;
  animation: tb-cursor 1s steps(2) infinite;
}
@keyframes tb-cursor {
  50% {
    opacity: 0;
  }
}

/* ── ScrollArea — auto-hiding macOS/iOS-style indicator ────────────────── */

.tb-scroll-wrap {
  position: relative;
  overflow: hidden;
  min-height: 0;
}
.tb-scroll-area {
  width: 100%;
  height: 100%;
  overflow-y: auto;
  overflow-x: hidden;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.tb-scroll-area::-webkit-scrollbar {
  width: 0;
  height: 0;
  display: none;
}
.tb-scroll-indicator {
  position: absolute;
  top: 0;
  right: 3px;
  width: 4px;
  background: rgba(10, 10, 9, 0.45);
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.32s ease;
}
.tb-scroll-indicator.on {
  opacity: 1;
}
.tb-scroll-indicator.dark {
  background: rgba(244, 242, 237, 0.55);
}
.tsubaki.tsubaki-dark .tb-scroll-indicator {
  background: rgba(244, 242, 237, 0.55);
}

/* ── Personas ─────────────────────────────────────────────────────────── */

.tb-personas {
  padding: 0;
}
.tb-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 0;
  border-bottom: 1px solid var(--line);
}
.tb-persona-card {
  padding: 16px 18px 18px;
  border-right: 1px solid var(--hair);
  border-bottom: 1px solid var(--hair);
  background: var(--paper);
  cursor: pointer;
  display: flex;
  flex-direction: column;
  position: relative;
  min-height: 240px;
  transition: background 0.1s;
}
.tb-persona-card:hover {
  background: var(--bg);
}
.tb-persona-card.on {
  background: var(--bg);
  outline: 1px solid var(--accent);
  outline-offset: -2px;
}
.tb-persona-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 12px;
}
.tb-persona-num {
  font-size: 10px;
  letter-spacing: 0.1em;
  color: var(--ink-3);
  font-variant-numeric: tabular-nums;
}
.tb-persona-dot {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  flex-shrink: 0;
  margin: 3px 3px 0 0;
  transition:
    background 0.15s ease,
    box-shadow 0.15s ease;
}
.tb-persona-name {
  font-size: 18px;
  letter-spacing: 0.06em;
  font-weight: 500;
  margin-bottom: 2px;
}
.tb-persona-accent {
  font-size: 10px;
  letter-spacing: 0.1em;
  color: var(--ink-3);
  margin-bottom: 10px;
}
.tb-persona-traits {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-bottom: 10px;
}
.tb-trait {
  font-size: 9px;
  letter-spacing: 0.1em;
  padding: 2px 6px;
  border: 1px solid var(--hair);
  color: var(--ink-2);
}
.tb-persona-desc {
  font-family: var(--tb-serif);
  font-size: 13px;
  color: var(--ink-2);
  font-style: italic;
  margin: 0 0 12px;
  flex: 1 1 auto;
  text-wrap: pretty;
}
.tb-persona-foot {
  display: flex;
  justify-content: space-between;
  border-top: 1px dashed var(--hair);
  padding-top: 8px;
  font-size: 10px;
}
.tb-persona-empty {
  background: repeating-linear-gradient(45deg, transparent 0 8px, var(--hair-2) 8px 9px);
}
.tb-persona-empty .tb-persona-name {
  color: var(--ink-3);
}
.tb-persona-drop {
  border: 1px dashed var(--hair);
  padding: 18px;
  text-align: center;
  font-size: 10px;
  letter-spacing: 0.1em;
  color: var(--ink-3);
  margin-top: auto;
}

/* ── Providers ────────────────────────────────────────────────────────── */

.tb-providers {
  padding: 0 0 24px;
}
.tb-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 11px;
}
.tb-table thead th {
  text-align: left;
  font-size: 9px;
  letter-spacing: 0.12em;
  color: var(--ink-3);
  padding: 12px 14px;
  border-bottom: 1px solid var(--line);
  background: var(--paper);
  font-weight: 500;
}
.tb-table tbody tr {
  border-bottom: 1px solid var(--hair);
  cursor: pointer;
  transition: background 0.08s;
}
.tb-table tbody tr:hover {
  background: var(--paper);
}
.tb-table tbody tr.on {
  background: var(--paper);
  outline: 1px solid var(--accent);
  outline-offset: -1px;
}
.tb-table td {
  padding: 12px 14px;
  vertical-align: middle;
}
.tb-table-vendor {
  font-weight: 600;
  letter-spacing: 0.04em;
}
.tb-table-note {
  color: var(--ink-3);
  font-size: 10px;
}
.tb-table-radio span {
  display: inline-block;
  width: 12px;
  height: 12px;
  border: 1px solid var(--line);
  position: relative;
}
.tb-table-radio span.on::after {
  content: "";
  position: absolute;
  inset: 2px;
  background: var(--accent-fg);
}

/* Per-provider model-picker inset — a detail row under a provider whose engine
   has a multi-model catalog (cascade). Single-model providers render no inset. */
.tb-prov-inset-row {
  cursor: default;
}
.tb-prov-inset-row.on {
  outline: 1px solid var(--accent);
  outline-offset: -1px;
}
/* The inset itself stays a real table-cell (so colSpan spans the full row); the
   flex layout lives on an inner wrapper — a flex `td` would drop out of the table
   box model and shrink to its content. */
.tb-prov-inset {
  padding: 8px 14px 10px !important;
  background: var(--hair-2);
  border-bottom: 1px solid var(--hair);
}
.tb-prov-inset-inner {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}
.tb-prov-inset-l {
  font-size: 9px;
  letter-spacing: 0.14em;
  color: var(--ink-3);
  text-transform: uppercase;
  flex: 0 0 auto;
}
.tb-prov-models {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.tb-prov-model {
  appearance: none;
  cursor: pointer;
  font: inherit;
  font-size: 10px;
  letter-spacing: 0.04em;
  padding: 4px 9px;
  background: var(--paper);
  color: var(--ink-2);
  border: 1px solid var(--hair);
  border-radius: 0;
  transition:
    background 0.08s,
    color 0.08s,
    border-color 0.08s;
}
.tb-prov-model:hover {
  background: var(--ink);
  color: var(--paper);
  border-color: var(--ink);
}
.tb-prov-model.on {
  font-weight: 600;
}

.tb-prov-detail {
  padding: 8px 28px 0;
}
.tb-prov-specs {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

/* ── Settings ─────────────────────────────────────────────────────────── */

.tb-settings {
  padding: 0 0 24px;
}
.tb-settings-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
  border-top: 1px solid var(--line);
}
.tb-settings-sec {
  padding: 18px 28px 20px;
  border-right: 1px solid var(--hair);
  border-bottom: 1px solid var(--hair);
}
.tb-field {
  margin-bottom: 14px;
}
.tb-field-hd {
  display: flex;
  justify-content: space-between;
  font-size: 9px;
  letter-spacing: 0.12em;
  color: var(--ink-3);
  text-transform: uppercase;
  margin-bottom: 6px;
}
.tb-field-hint {
  color: var(--ink-2);
  font-variant-numeric: tabular-nums;
}

.tb-select {
  appearance: none;
  background: var(--paper);
  border: 1px solid var(--line);
  font: inherit;
  color: var(--ink);
  padding: 7px 24px 7px 10px;
  font-size: 11px;
  width: 100%;
  border-radius: 0;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='10' height='6' viewBox='0 0 10 6'><path fill='currentColor' d='M0 0h10L5 6z'/></svg>");
  background-repeat: no-repeat;
  background-position: right 8px center;
}

.tb-meter {
  height: 8px;
  border: 1px solid var(--line);
  background: repeating-linear-gradient(90deg, var(--hair-2) 0 1px, transparent 1px 12px);
  position: relative;
  overflow: hidden;
}
.tb-meter > span {
  display: block;
  height: 100%;
}

.tb-range {
  width: 100%;
}
.tb-range-scale {
  display: flex;
  justify-content: space-between;
  font-size: 9px;
  color: var(--ink-3);
  margin-top: 4px;
}

.tb-switch {
  appearance: none;
  border: 1px solid var(--line);
  background: var(--paper);
  color: var(--ink);
  font: inherit;
  font-size: 9px;
  letter-spacing: 0.14em;
  cursor: pointer;
  display: inline-grid;
  grid-template-columns: 1fr 22px 1fr;
  align-items: center;
  gap: 4px;
  padding: 4px 8px;
  border-radius: 0;
}
.tb-switch-l,
.tb-switch-r {
  color: var(--ink-3);
}
.tb-switch.on .tb-switch-r {
  color: var(--accent);
  font-weight: 600;
}
.tb-switch:not(.on) .tb-switch-l {
  color: var(--ink);
  font-weight: 600;
}
.tb-switch-knob {
  display: inline-block;
  width: 14px;
  height: 8px;
  background: var(--ink-3);
  position: relative;
}
.tb-switch.on .tb-switch-knob {
  background: var(--accent);
}
.tb-switch-knob::after {
  content: "";
  position: absolute;
  width: 6px;
  height: 12px;
  top: -2px;
  left: 0;
  background: var(--paper);
  border: 1px solid var(--line);
  transition: left 0.12s;
}
.tb-switch.on .tb-switch-knob::after {
  left: 8px;
}

.tb-tool {
  display: grid;
  grid-template-columns: 130px 1fr auto;
  gap: 12px;
  align-items: center;
  padding: 8px 0;
  border: 0;
  border-bottom: 1px dashed var(--hair);
  background: transparent;
  width: 100%;
  font: inherit;
  text-align: left;
  color: var(--ink);
  font-size: 11px;
  cursor: pointer;
  transition:
    background 0.08s,
    opacity 0.12s;
}
.tb-tool:hover {
  background: var(--hair-2);
}
.tb-tool.off {
  opacity: 0.55;
}
.tb-tool:last-child {
  border-bottom: 0;
}
.tb-tool-name {
  color: var(--accent);
  font-weight: 500;
}
.tb-tool-label {
  color: var(--ink-2);
}
.tb-tool-status {
  font-size: 9px;
  letter-spacing: 0.12em;
}
.tb-tool-status.on {
  color: var(--ink);
}
.tb-tool-status.off {
  color: var(--ink-3);
}

/* ── ToolsButton popover ──────────────────────────────────────────────── */

.tb-tools-wrap {
  position: relative;
  display: inline-flex;
}
.tb-btn-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 13px;
  height: 13px;
  background: var(--accent);
  color: var(--accent-fg);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0;
  padding: 0 3px;
  margin-left: 4px;
  font-variant-numeric: tabular-nums;
}
.tb-btn:hover:not(:disabled) .tb-btn-badge,
.tb-btn-on .tb-btn-badge {
  background: var(--accent-fg);
  color: var(--accent);
}
.tb-tools-pop {
  position: absolute;
  bottom: calc(100% + 8px);
  right: 0;
  min-width: 280px;
  background: var(--paper);
  border: 1px solid var(--line);
  box-shadow: 4px 4px 0 var(--line);
  z-index: 50;
  font-size: 11px;
  animation: tb-pop-in 0.16s ease-out both;
}
@keyframes tb-pop-in {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.tb-tools-pop::after {
  content: "";
  position: absolute;
  top: 100%;
  right: 14px;
  width: 8px;
  height: 8px;
  background: var(--paper);
  border-right: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  transform: translateY(-50%) rotate(45deg);
}
.tb-tools-pop-hd {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 12px;
  font-size: 9px;
  letter-spacing: 0.14em;
  color: var(--ink-3);
  text-transform: uppercase;
  border-bottom: 1px solid var(--hair);
}
.tb-tools-pop-count {
  color: var(--ink-2);
  font-variant-numeric: tabular-nums;
}
.tb-tools-pop-body {
  display: flex;
  flex-direction: column;
}
.tb-tools-pop-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 16px;
  padding: 8px 12px;
  border-bottom: 1px dashed var(--hair);
}
.tb-tools-pop-row:last-child {
  border-bottom: 0;
}
/* Tool ids never break; the label (with its PREVIEW tag) wraps instead. */
.tb-tools-pop-name {
  color: var(--accent);
  font-weight: 500;
  font-size: 11px;
  white-space: nowrap;
  flex: 0 0 auto;
}
.tb-tools-pop-label {
  color: var(--ink-2);
  font-size: 10px;
  text-align: right;
  min-width: 0;
}
.tb-tools-pop-foot {
  padding: 8px 12px;
