  gap: 12px;
}
/* Closed, the layer is visibility-hidden so the drawer's buttons leave the
   tab order. */
.tb-drawer-layer {
  position: fixed;
  inset: 0;
  z-index: 40;
  visibility: hidden;
  transition: visibility 0s linear 0.22s;
}
.tb-drawer-layer.open {
  visibility: visible;
  transition-delay: 0s;
}
.tb-drawer-scrim {
  position: absolute;
  inset: 0;
  background: color-mix(in srgb, var(--ink) 38%, transparent);
  opacity: 0;
  transition: opacity 0.22s ease;
}
.tb-drawer-layer.open .tb-drawer-scrim {
  opacity: 1;
}
.tb-drawer {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  width: 240px;
  max-width: 80%;
  display: flex;
  border-right: 1px solid var(--line);
  box-shadow: 4px 0 0 var(--line);
  transform: translateX(calc(-100% - 6px));
  transition: transform 0.22s cubic-bezier(0.2, 0.7, 0.3, 1);
}
.tb-drawer-layer.open .tb-drawer {
  transform: none;
}
/* The reused desktop Sidebar fills the drawer; the drawer owns the border. */
.tb-drawer .tb-side {
  flex: 1 1 auto;
  border-right: 0;
  padding-top: 22px;
}
@media (prefers-reduced-motion: reduce) {
  .tb-drawer,
  .tb-drawer-scrim {
    transition: none;
  }
}
/* Provider notes don't fit a phone; the active provider's specs carry the
   detail instead. */
.tb-mobile .tb-th-note,
.tb-mobile .tb-table-note {
  display: none;
}
.tb-mobile .tb-settings-sec {
  border-right: 0;
}

