await write('app/api/openai-live/session/route.ts', `// Creates an OPENAI LIVE (GPT-Live) WebRTC session for the browser.
//
// GPT-Live has no browser token: the server creates the session with the
// project key, forwarding the browser's SDP offer and returning the answer.
// That puts everything the persona knows at startup on the server:
//   - the persona prompt and voice (resolveLiveAgent), never from the request,
//   - recalled mem0 memories (best-effort, capped at RECALL_TIMEOUT_MS),
//   - a continued OPENAI LIVE call, read from Archil for this visitor only,
//   - the greeting instruction, last in the startup input.
// It then stores a call record for the visitor and attaches a sideband that
// records the transcript until the call closes (live-capture.ts).
//
// POST { sdp, personaId, lang, userId?, memory?, resumeId? }
//   → { sdp, callId, greeting }   callId is null when the call isn't stored.
// Storage and memory never fail or noticeably delay the call.
//
// Dev only: OPENAI_API_KEY, MEM0_API_KEY, ARCHIL_API_KEY come from fnox.

import { PERSONAS } from "@/lib/data";
import { LANGS, type Lang } from "@/lib/lang";
import { startLiveCapture } from "@/lib/conversations/live-capture";
import { buildLiveInput } from "@/lib/conversations/live-seed";
import { createCall, getCall, nowSecs, type LiveCallRecord } from "@/lib/conversations/live-store";
import { isLiveCallId, isMemoryUserId, newLiveCallId } from "@/lib/memory/ids";
import { ingestLiveCall } from "@/lib/memory/live-ingest";
import { listRecentMemories, mem0ApiKey } from "@/lib/memory/mem0-rest";
import { resolveLiveAgent } from "@/lib/realtime/openai-live-agent";
import { archilConfigured } from "@/lib/storage/archil";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const SESSIONS_URL = "https://api.openai.com/v1/live/sessions";
const MAX_SDP_CHARS = 20_000;
const RECALL_LIMIT = 20;
const RECALL_TIMEOUT_MS = 2000;
const STORE_TIMEOUT_MS = 3000;

interface SessionRequest {
  sdp?: unknown;
  personaId?: unknown;
  lang?: unknown;
  userId?: unknown;
  memory?: unknown;
  resumeId?: unknown;
}

function fail(error: string, status: number): Response {
  return Response.json({ error }, { status });
}

/** The promise's value, or \`fallback\` if it fails or takes longer than \`ms\`. */
async function within<T>(p: Promise<T>, ms: number, fallback: T, what: string): Promise<T> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  const timeout = new Promise<T>((resolve) => {
    timer = setTimeout(() => resolve(fallback), ms);
  });
  try {
    return await Promise.race([p, timeout]);
  } catch (err) {
    console.warn(\`[openai-live] \${what} failed:\`, err instanceof Error ? err.message : err);
    return fallback;
  } finally {
    clearTimeout(timer);
  }
}

/** "429 · You have no credits remaining." — OpenAI's own reason, first sentence. */
async function describeFailure(res: Response): Promise<string> {
  try {
    const body = (await res.json()) as { error?: { message?: string; code?: string } };
    const reason = body.error?.message?.split(/(?<=\\.)\\s/)[0] ?? body.error?.code;
    if (reason) return \`\${res.status} · \${reason}\`;
  } catch {
    // non-JSON error body
  }
  return String(res.status);
}

export async function POST(req: Request): Promise<Response> {
  const apiKey = process.env.OPENAI_API_KEY;
  if (!apiKey) return fail("OPENAI_API_KEY is not set on the server (provide it via fnox).", 500);

  let body: SessionRequest;
  try {
    body = (await req.json()) as SessionRequest;
  } catch {
    return fail("Invalid JSON body.", 400);
  }
  const { sdp, personaId, lang, userId, memory, resumeId } = body;
  if (typeof sdp !== "string" || !sdp.trim() || sdp.length > MAX_SDP_CHARS) {
    return fail("An SDP offer is required.", 400);
  }
  const persona = PERSONAS.find((p) => p.id === personaId);
  if (!persona) return fail("personaId is unknown.", 400);
  const sessionLang: Lang = LANGS.includes(lang as Lang) ? (lang as Lang) : "en";
  // Without a visitor id the call simply isn't remembered or stored.
  const visitor = isMemoryUserId(userId) ? userId : null;
  const stored = visitor !== null && archilConfigured();
  const wantsMemory = memory === true;

  const mem0Key = mem0ApiKey();
  const recall =
    visitor && wantsMemory && mem0Key
      ? within(
          listRecentMemories(mem0Key, visitor, RECALL_LIMIT).then((ms) =>
            ms.map((m) => m.memory).filter(Boolean),
          ),
          RECALL_TIMEOUT_MS,
          [] as string[],
          "recall",
        )
      : Promise.resolve([] as string[]);
  const resume =
    stored && isLiveCallId(resumeId)
      ? within(getCall(visitor, resumeId), STORE_TIMEOUT_MS, null, "resume load")
      : Promise.resolve(null);
  const [memories, resumed] = await Promise.all([recall, resume]);

  const agent = resolveLiveAgent(persona.id, sessionLang, { resumed: !!resumed });
  const input = buildLiveInput({
    memories,
    resume: resumed ? { lang: resumed.lang, transcript: resumed.turns } : null,
    greeting: agent.greeting,
    lang: sessionLang,
  });

  let upstream: Response;
  try {
    upstream = await fetch(SESSIONS_URL, {
      method: "POST",
      headers: { Authorization: \`Bearer \${apiKey}\`, "Content-Type": "application/json" },
      body: JSON.stringify({
        session: {
          model: agent.model,
          instructions: agent.instructions,
          input,
          audio: { output: { voice: agent.voice.param } },
          // Client delegation with no backend behind it: the prompt says not to
          // delegate, and the browser answers a stray delegation anyway.
          delegation: { type: "client" },
        },
        transport: { type: "webrtc", sdp },
      }),
    });
  } catch (err) {
    return fail(\`Failed to reach OpenAI: \${err instanceof Error ? err.message : "network error"}\`, 502);
  }
  if (!upstream.ok) return fail(\`OpenAI Live: \${await describeFailure(upstream)}\`, 502);
  const created = (await upstream.json()) as {
    session?: { id?: string };
    transport?: { sdp?: string };
  };
  const sessionId = created.session?.id;
  const answer = created.transport?.sdp;
  if (!sessionId || !answer) return fail("OpenAI Live returned no session.", 502);

  let callId: string | null = null;
  if (stored) {
    const now = nowSecs();
    const record: LiveCallRecord = {
      v: 1,
      id: newLiveCallId(),
      userId: visitor,
      personaId: persona.id,
      lang: sessionLang,
      memory: wantsMemory,
      startedAt: now,
      updatedAt: now,
      status: "open",
      ...(resumed ? { resumedFrom: resumed.id } : {}),
      turns: [],
    };
    const ok = await within(
      createCall(record).then(() => true),
      STORE_TIMEOUT_MS,
      false,
      "store",
    );
    if (ok) {
      callId = record.id;
      // Attach right away: the sideband replays only the last 3 seconds.
      startLiveCapture({ apiKey, sessionId, record, onFinished: ingestLiveCall });
    }
  }

  return Response.json(
    { sdp: answer, callId, greeting: agent.greeting },
    { headers: { "Cache-Control": "no-store" } },
  );
}
`);
'ok'

await write('lib/realtime/audio-level.ts', `// Orb levels from Web Audio analysers.

const VOL_GAIN = 3.5;

/** RMS of an analyser's current time-domain frame, scaled to a 0..1 orb level. */
export function analyserLevel(
  analyser: AnalyserNode | null,
  buf: Float32Array<ArrayBuffer> | null,
): number {
  if (!analyser || !buf) return 0;
  analyser.getFloatTimeDomainData(buf);
  let sum = 0;
  for (let i = 0; i < buf.length; i++) sum += buf[i] * buf[i];
  return Math.min(1, Math.sqrt(sum / buf.length) * VOL_GAIN);
}
`);

await write('lib/realtime/live-connection.ts', `"use client";

// One OPENAI LIVE call's browser side: microphone, WebRTC peer connection,
// \`oai-events\` data channel, playback element and level analysers.
//
// Each call owns its own instance, so a call still closing gracefully (waiting
// for session.closed) can never touch the call that replaced it. The server
// creates the session (app/api/openai-live/session); the browser only carries
// the media and shows what it hears.
//
// Playback goes straight through an <audio> element so Chrome's echo canceller
// keeps the remote track as its reference; the output analyser reads the remote
// stream passively and is never connected to the speakers.

import type { Lang } from "@/lib/lang";
import { analyserLevel } from "./audio-level";

const ICE_GATHER_TIMEOUT_MS = 10_000;
const CLOSE_TIMEOUT_MS = 5000;

/** A data-channel event, loosely typed: only the fields the client reads. */
export interface LiveServerEvent {
  type: string;
  event_id?: string;
  delta?: string;
  start_ms?: number;
  end_ms?: number;
  reason?: string;
  delegation?: { id?: string };
  error?: { message?: string; code?: string | null };
}

export interface LiveStartParams {
  personaId?: string;
  lang: Lang;
  /** The visitor's memory id; null skips memory and storage. */
  userId: string | null;
  memory: boolean;
  /** A stored OPENAI LIVE call to continue. */
  resumeId: string | null;
}

export type LiveOpenResult =
  | { ok: true; callId: string | null; greeting: string }
  | { ok: false; caption: string }
  | { ok: false; stale: true };

export interface LiveConnectionHandlers {
  onEvent: (ev: LiveServerEvent) => void;
  /** The connection went away without session.closed. */
  onDrop: () => void;
}

function waitForIce(pc: RTCPeerConnection): Promise<void> {
  if (pc.iceGatheringState === "complete") return Promise.resolve();
  return new Promise((resolve) => {
    // Past the timeout, send what has been gathered; the server answer still works
    // with partial candidates on most networks.
    const timer = setTimeout(done, ICE_GATHER_TIMEOUT_MS);
    function done() {
      clearTimeout(timer);
      pc.removeEventListener("icegatheringstatechange", onState);
      resolve();
    }
    function onState() {
      if (pc.iceGatheringState === "complete") done();
    }
    pc.addEventListener("icegatheringstatechange", onState);
  });
}

export class LiveConnection {
  private pc: RTCPeerConnection | null = null;
  private dc: RTCDataChannel | null = null;
  private stream: MediaStream | null = null;
  private audio: HTMLAudioElement | null = null;
  private ctx: AudioContext | null = null;
  private inAnalyser: AnalyserNode | null = null;
  private outAnalyser: AnalyserNode | null = null;
  private inBuf: Float32Array<ArrayBuffer> | null = null;
  private outBuf: Float32Array<ArrayBuffer> | null = null;
  private disposed = false;
  private closing = false;
  private resolveClosed: (() => void) | null = null;
  private micEnabled = true;

  constructor(private readonly handlers: LiveConnectionHandlers) {}

  /** Connect. \`isStale\` reports a hang-up or a newer call; setup backs off when it does. */
  async open(params: LiveStartParams, isStale: () => boolean): Promise<LiveOpenResult> {
    const stale = () => this.disposed || isStale();

    try {
      this.stream = await navigator.mediaDevices.getUserMedia({
        audio: { channelCount: 1, echoCancellation: true, noiseSuppression: true, autoGainControl: true },
      });
    } catch {
      return { ok: false, caption: "— microphone permission denied —" };
    }
    if (stale()) return { ok: false, stale: true };
    this.applyMic();

    const ctx = new AudioContext();
    this.ctx = ctx;
    if (ctx.state === "suspended") await ctx.resume();
    if (stale()) return { ok: false, stale: true };
    this.inAnalyser = ctx.createAnalyser();
    this.inAnalyser.fftSize = 1024;
    ctx.createMediaStreamSource(this.stream).connect(this.inAnalyser);
    this.inBuf = new Float32Array(this.inAnalyser.fftSize);

    const pc = new RTCPeerConnection();
    this.pc = pc;
    const audio = document.createElement("audio");
    audio.autoplay = true;
    this.audio = audio;
    pc.ontrack = (e) => {
      const remote = e.streams[0] ?? new MediaStream([e.track]);
      audio.srcObject = remote;
      void audio.play().catch(() => {
        // Autoplay is allowed after the CALL click; nothing to recover here.
      });
      try {
        const out = ctx.createAnalyser();
        out.fftSize = 1024;
        ctx.createMediaStreamSource(remote).connect(out);
        this.outAnalyser = out;
        this.outBuf = new Float32Array(out.fftSize);
      } catch {
        // levels are best-effort
      }
    };
    pc.onconnectionstatechange = () => {
      if (pc.connectionState === "failed" || pc.connectionState === "closed") this.dropped();
    };
    this.stream.getTracks().forEach((t) => pc.addTrack(t, this.stream!));

    // The data channel must exist before the offer.
    const dc = pc.createDataChannel("oai-events");
    this.dc = dc;
    dc.onmessage = (m) => {
      if (this.disposed) return;
      let ev: LiveServerEvent;
      try {
        ev = JSON.parse(typeof m.data === "string" ? m.data : "") as LiveServerEvent;
      } catch {
        return;
      }
      if (ev.type === "session.closed") this.resolveClosed?.();
      this.handlers.onEvent(ev);
    };
    dc.onclose = () => this.dropped();

    let offerSdp: string | undefined;
    try {
      await pc.setLocalDescription(await pc.createOffer());
      await waitForIce(pc);
      offerSdp = pc.localDescription?.sdp;
    } catch {
      return { ok: false, caption: "— could not establish WebRTC session —" };
    }
    if (stale()) return { ok: false, stale: true };
    if (!offerSdp) return { ok: false, caption: "— could not establish WebRTC session —" };

    let data: { sdp?: string; callId?: string | null; greeting?: string; error?: string };
    try {
      const res = await fetch("/api/openai-live/session", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ ...params, sdp: offerSdp }),
      });
      data = (await res.json()) as typeof data;
      if (!res.ok) return { ok: false, caption: \`— \${data.error ?? "session error"} —\` };
    } catch {
      return { ok: false, caption: "— could not reach session endpoint —" };
    }
    if (stale()) {
      // The session exists upstream; close it rather than leave it billing.
      return { ok: false, stale: true };
    }
    if (!data.sdp) return { ok: false, caption: "— could not establish WebRTC session —" };
    try {
      await pc.setRemoteDescription({ type: "answer", sdp: data.sdp });
    } catch {
      return { ok: false, caption: "— could not establish WebRTC session —" };
    }
    return { ok: true, callId: data.callId ?? null, greeting: data.greeting ?? "" };
  }

  send(ev: Record<string, unknown>): void {
    const dc = this.dc;
    if (dc && dc.readyState === "open") dc.send(JSON.stringify(ev));
  }

  setMicEnabled(enabled: boolean): void {
    this.micEnabled = enabled;
    this.applyMic();
  }

  private applyMic(): void {
    // \`enabled = false\` sends silence: the session keeps running, as GPT-Live expects.
    this.stream?.getAudioTracks().forEach((t) => (t.enabled = this.micEnabled));
  }

  /** Silence playback locally (the model's speech keeps flowing; the analyser still hears it). */
  setOutputMuted(muted: boolean): void {
    if (this.audio) this.audio.muted = muted;
  }

  inputLevel(): number {
    return this.micEnabled ? analyserLevel(this.inAnalyser, this.inBuf) : 0;
  }

  outputLevel(): number {
    return analyserLevel(this.outAnalyser, this.outBuf);
  }

  /**
   * Hang up gracefully: session.close, then wait for session.closed (so the
   * server-side capture finalizes cleanly) or a timeout, then release.
   */
  async close(): Promise<void> {
    if (this.disposed || this.closing) return;
    this.closing = true;
    if (this.dc?.readyState === "open") {
      const closed = new Promise<void>((resolve) => {
        this.resolveClosed = resolve;
        setTimeout(resolve, CLOSE_TIMEOUT_MS);
      });
      this.send({ type: "session.close" });
      // Nothing more should reach the caller while the session drains.
      this.setMicEnabled(false);
      this.setOutputMuted(true);
      await closed;
    }
    this.dispose();
  }

  private dropped(): void {
    if (this.disposed || this.closing) return;
    this.handlers.onDrop();
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    try {
      this.dc?.close();
    } catch {
      // already closing
    }
    try {
      this.pc?.close();
    } catch {
      // already closing
    }
    this.stream?.getTracks().forEach((t) => t.stop());
    if (this.audio) this.audio.srcObject = null;
    void this.ctx?.close();
    this.dc = null;
    this.pc = null;
    this.stream = null;
    this.audio = null;
    this.ctx = null;
    this.inAnalyser = null;
    this.outAnalyser = null;
  }
