const scr = `${sp}/live-tests.ts`;
await write(scr, `
import { appendTranscriptDelta, settledTurns } from "@/lib/conversations/live-transcript";
import { decodeCursor, encodeCursor, liveFloor, takeLiveWindow } from "@/lib/conversations/history-cursor";
import { buildLiveInput, estimateTokens } from "@/lib/conversations/live-seed";
import { resolveLiveAgent } from "@/lib/realtime/openai-live-agent";
const out: Record<string, unknown> = {};
let t = appendTranscriptDelta([], "agent", "Hello ", 0, 300);
t = appendTranscriptDelta(t, "agent", "there.", 300, 600);
t = appendTranscriptDelta(t, "user", "Hi", 700, 900);
t = appendTranscriptDelta(t, "agent", " mm-hm", 800, 950); // overlap continues? prev agent end 600, start 800 -> gap 200 <= 800 merges
t = appendTranscriptDelta(t, "user", " again", 1000, 1200);
t = appendTranscriptDelta(t, "agent", "New turn", 5000, 5400);
out.turns = settledTurns(t);
const c = encodeCursor({ e: "abc", ed: false, l: "99999999999_olc_" + "a".repeat(32) });
out.cursor = [decodeCursor(c), decodeCursor("bad!"), decodeCursor(encodeCursor({ l: "x" } as never))];
out.floor = [liveFloor(true, []), liveFloor(false, []), liveFloor(false, [5, 3, 9])];
out.window = takeLiveWindow([{ startedAt: 10 }, { startedAt: 6 }, { startedAt: 2 }], 5, 30);
const agent = resolveLiveAgent("aria", "ja", { resumed: true });
const long = Array.from({ length: 300 }, (_, i) => ({ who: i % 2 ? "agent" : "user", text: "長い会話の一行です。".repeat(20) })) as never;
const input = buildLiveInput({ memories: ["Likes tea", "Lives in Osaka"], resume: { lang: "en", transcript: long }, greeting: agent.greeting, lang: "ja" });
out.seed = { count: input.length, tokens: input.reduce((s, m) => s + estimateTokens(m.content[0].text), 0), first: input[0].content[0].text.slice(0, 80), roles: input.slice(0, 3).map((m) => m.role), last: input.at(-1)!.content[0].text.slice(0, 120) };
out.voice = agent.voice; out.instrLen = agent.instructions.length;
console.log(JSON.stringify(out, null, 1));
`);
const r = await $`bun ${scr}`.nothrow();
r.output

