await write(scr2, `
import { createCall, getCall, listIndex, isListable, summarizeCall, type LiveCallRecord } from "${repo}/lib/conversations/live-store";
import { listHistory, getHistoryDetail } from "${repo}/lib/conversations/history";
import { archilDisk, ARCHIL_ROOT } from "${repo}/lib/storage/archil";
import { newLiveCallId } from "${repo}/lib/memory/ids";
const userId = "tsubaki-" + crypto.randomUUID();
const now = Math.floor(Date.now() / 1000);
const mk = (startedAt: number, turns: LiveCallRecord["turns"], status: LiveCallRecord["status"]): LiveCallRecord => ({ v: 1, id: newLiveCallId(), userId, personaId: "aria", lang: "en", memory: false, startedAt, updatedAt: startedAt, status, turns });
const recs = [mk(now - 300, [{ who: "user", text: "oldest call" }], "done"), mk(now - 100, [{ who: "user", text: "newest call" }, { who: "agent", text: "hi" }], "done"), mk(now - 200, [{ who: "agent", text: "agent only" }], "done"), mk(now - 50, [{ who: "user", text: "still open" }], "open")];
const out: Record<string, unknown> = {};
try {
  for (const r of recs) await createCall(r);
  const idx = await listIndex(userId, null, 10);
  out.order = idx.entries.map((e) => recs.find((r) => r.id === e.callId)!.turns[0].text);
  const page2 = await listIndex(userId, idx.entries[1].name, 10);
  out.afterSecond = page2.entries.length;
  const got = await getCall(userId, recs[1].id);
  out.get = got ? summarizeCall(got) : null;
  out.wrongUser = await getCall("tsubaki-" + crypto.randomUUID(), recs[1].id);
  out.listable = recs.map((r) => isListable(r));
  const page = await listHistory({ liveStore: true }, userId);
  out.history = { titles: page.items.map((i) => i.title), next: page.nextCursor };
  const d = await getHistoryDetail({ liveStore: true }, userId, recs[0].id);
  out.detail = d.transcript;
  try { await getHistoryDetail({ liveStore: true }, "tsubaki-" + crypto.randomUUID(), recs[0].id); } catch (e) { out.otherUserDetail = (e as { status?: number }).status; }
} finally {
  const disk = await archilDisk();
  const all = await disk.listObjects(ARCHIL_ROOT + "/openai-live/", { recursive: true });
  const mine = all.objects.filter((o) => o.key.includes(userId));
  for (const o of mine) await disk.deleteObject(o.key);
  const left = (await disk.listObjects(ARCHIL_ROOT + "/openai-live/", { recursive: true })).objects.filter((o) => o.key.includes(userId));
  out.cleanup = { deleted: mine.length, left: left.length };
}
console.log(JSON.stringify(out, null, 1));
`);
const r3 = await $`fnox exec -- bun ${scr2}`.nothrow();
r3.output.slice(-4000)

