const u = self.testUid, cid = self.sessResp.callId;
const [lst, det, bad, other] = await Promise.all([
  $`curl -s -X POST http://localhost:3000/api/conversations -H 'Content-Type: application/json' --data-binary ${JSON.stringify({userId: u})}`.nothrow(),
  $`curl -s -X POST http://localhost:3000/api/conversations/${cid} -H 'Content-Type: application/json' --data-binary ${JSON.stringify({userId: u})}`.nothrow(),
  $`curl -s -X POST http://localhost:3000/api/conversations -H 'Content-Type: application/json' --data-binary ${JSON.stringify({userId: u, cursor: 'zzz'})}`.nothrow(),
  $`curl -s -w " %{http_code}" -X POST http://localhost:3000/api/conversations/${cid} -H 'Content-Type: application/json' --data-binary ${JSON.stringify({userId: 'tsubaki-00000000-0000-4000-8000-000000000000'})}`.nothrow(),
]);
const scr4 = `${sp}/cleanup.ts`;
await write(scr4, `
import { archilDisk, ARCHIL_ROOT } from "${repo}/lib/storage/archil";
const u = process.argv[2];
