const all = (await disk.listObjects(ARCHIL_ROOT + "/openai-live/", { recursive: true })).objects.filter((o) => o.key.includes(u)).sort((a, b) => Number(a.key.endsWith("/")) - Number(b.key.endsWith("/")) || b.key.length - a.key.length);
for (const o of all) await disk.deleteObject(o.key);
console.log("deleted", all.length);
`);
const cl = await $`fnox exec -- bun ${scr4} ${u}`.nothrow();
({lst: lst.stdout.slice(0,600), det: det.stdout.slice(0,400), bad: bad.stdout, other: other.stdout, cleanup: cl.output})

