  css_selector?: string
  /** Target process ID. */
  pid?: number
  /** For multi-call work, prefer a short public session label and repeat it on every call that accepts it. */
  session?: string
  /** Target window ID from list_windows. */
  window_id?: number
}

{
  /** Targets a specific page by ID. */
  pageId: number
  /** Logpoints formatted as <url>:<lineNumber>[:<columnNumber>] <expression>. The url is a script URL or the path of an original source file from a source map, exact or as a path suffix (e.g. "src/app.ts"). Line and column numbers are 1-based in the coordinates of the url; a line without executable code moves to the next possible location. The expression is evaluated like console.log() arguments in the scope of the location, where local variables are accessible by their original names, and runs before the line executes, so a variable declared on that line is not set yet. list_console_messages shows objects as [object Object]: read them with get_console_message, or log JSON.stringify(value) for plain data. Example: "src/cart.ts:42 'cart total:', cart.total, cart.items.length". Pass an empty array to remove all logpoints. */
  logpoints: string[]
}

{
  /** Targets a specific page by ID. */
  pageId: number
  /** Whether to include all possible information available in the full a11y tree. Default is false. */
  verbose?: boolean
  /** The absolute path, or a path relative to the current working directory, to save the snapshot to instead of attaching it to the response. */
  filePath?: string
}

{
  /** Targets a specific page by ID. */
  pageId: number
  /** Throttle network. Omit to disable throttling. */
  networkConditions?: "Offline" | "Slow 3G" | "Fast 3G" | "Slow 4G" | "Fast 4G"
  /** Represents the CPU slowdown factor. Omit or set the rate to 1 to disable throttling */
  cpuThrottlingRate?: number
  /** Geolocation (`<latitude>,<longitude>`) to emulate. Latitude between -90 and 90. Longitude between -180 and 180. Omit to clear the geolocation override. */
  geolocation?: string
  /** User agent to emulate. Omit or set to empty string to clear the user agent override. */
  userAgent?: string
  /** Emulate the dark or the light mode. Omit or set to "auto" to reset to the default. */
  colorScheme?: "dark" | "light" | "auto"
  /** Emulate the `forced-colors` CSS media feature. Omit or set to "auto" to reset to the default. */
  forcedColors?: "active" | "none" | "auto"
  /** Emulate the `prefers-contrast` CSS media feature. Omit or set to "auto" to reset to the default. */
  prefersContrast?: "more" | "less" | "custom" | "no-preference" | "auto"
  /** Emulate the `prefers-reduced-motion` CSS media feature. Omit or set to "auto" to reset to the default. */
  prefersReducedMotion?: "reduce" | "no-preference" | "auto"
  /** Emulate device viewports '<width>x<height>x<devicePixelRatio>[,mobile][,touch][,landscape]'. 'touch' and 'mobile' to emulate mobile devices. 'landscape' to emulate landscape mode. Omit to clear the viewport override. */
  viewport?: string
  /** Extra HTTP headers as a JSON string object, e.g. {"X-Custom": "value", "Authorization": "Bearer token"}. Headers are included into every HTTP request originating from the page and persist across navigations until cleared. Pass an empty string to clear all extra headers. */
  extraHttpHeaders?: string
}

