const lc = 'lib/realtime/live-connection.ts';
let lcT = await file(lc).text();
lcT = lcT.replaceAll('if (stale()) return { ok: false, stale: true };', 'if (stale()) return this.backOff();');
lcT = lcT.replace(`  send(ev: Record<string, unknown>): void {`, `  /** A hang-up or newer call landed mid-setup: release what was acquired since. */
  private backOff(): LiveOpenResult {
    this.dispose();
    return { ok: false, stale: true };
  }

  send(ev: Record<string, unknown>): void {`);
lcT = lcT.replace(`  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;`, `  /**
   * Release everything. Safe to call again: setup still in flight when a call
   * is hung up acquires resources after the first call, and backOff() releases
   * them with a second one.
   */
  dispose(): void {
    this.disposed = true;`);
await write(lc, lcT);
const ck = await Promise.all([
  tools.Grep({pattern: 'press CALL to continue|press CALL to begin', path: 'lib', output_mode: 'content', '-n': true}),
  tools.Grep({pattern: 'isLive\\(stateRef|const start = useCallback', path: 'lib/realtime', output_mode: 'content', '-n': true, '-A': 3}),
  tools.Grep({pattern: 'restart|\\.start\\(\\)', path: 'hooks/use-session-routing.ts', output_mode: 'content', '-n': true}),
]);
ck.map(x=>x.content).join('\n=====\n')

