    this.disposed = true;
    try {
      this.dc?.close();
    } catch {
      // already closing
    }
    try {
      this.pc?.close();
    } catch {
      // already closing
    }
    this.stream?.getTracks().forEach((t) => t.stop());
    if (this.audio) this.audio.srcObject = null;
    void this.ctx?.close();
    this.dc = null;
    this.pc = null;
    this.stream = null;
